const calmQ = matchMedia('(prefers-reduced-motion: reduce)');
const cv = root.querySelector('.fxw-flare__canvas');
const ctx = cv.getContext('2d');
const sunBtn = root.querySelector('.fxw-flare__sun');
const apIn = root.querySelector('.fxw-flare__ap input');
const radios = [...root.querySelectorAll('.fxw-flare__blades input')];
const out = {
  f: root.querySelector('[data-f]'), blades: root.querySelector('[data-blades]'),
  star: root.querySelector('[data-star]'), clear: root.querySelector('[data-clear]')
};
const sr = root.querySelector('.fxw-flare__sr');
const group = 'fxw-flare-' + Math.random().toString(36).slice(2, 8);
radios.forEach((r) => { r.name = group; });

const STOPS = [1.4, 2, 2.8, 4, 5.6, 8, 11, 16];
const [probe, pctx] = (() => { const c = document.createElement('canvas'); c.width = c.height = 1; return [c, c.getContext('2d', { willReadFrequently: true })]; })();
function rgb(name) {
  pctx.clearRect(0, 0, 1, 1);
  pctx.fillStyle = '#888';
  pctx.fillStyle = getComputedStyle(root).getPropertyValue(name).trim() || '#888';
  pctx.fillRect(0, 0, 1, 1);
  const d = pctx.getImageData(0, 0, 1, 1).data;
  return [d[0], d[1], d[2]];
}
const mix = (a, b, t) => a.map((v, i) => Math.round(v + (b[i] - v) * t));
const css = (c, a = 1) => 'rgb(' + c[0] + ' ' + c[1] + ' ' + c[2] + ' / ' + a + ')';

// Ghosts sit on the line from the sun through the optical centre: P = C + (S − C)·t.
// Negative t lands on the far side of centre, mirrored, as real internal reflections do.
const GHOSTS = [
  { t: 0.62, r: 0.035, a: 0.16, tint: [255, 196, 120] },
  { t: 0.3, r: 0.06, a: 0.08, tint: [140, 255, 170] },
  { t: -0.18, r: 0.025, a: 0.2, tint: [255, 150, 210] },
  { t: -0.42, r: 0.075, a: 0.07, tint: [120, 220, 255] },
  { t: -0.7, r: 0.045, a: 0.13, tint: [180, 255, 140] },
  { t: -1.0, r: 0.11, a: 0.05, tint: [255, 170, 110] },
  { t: -1.35, r: 0.06, a: 0.09, tint: [200, 160, 255] },
];

let W = 0, H = 0, dpr = 1, C = null, near = [], far = [];
const sun = { x: 0.72, y: 0.38, tx: 0.72, ty: 0.38 };
let stop = 5, blades = 7, vis = 1, visible = false, raf = 0, last = 0, t = 0, userAt = -1e9, dragging = false;

function rng(seed) {
  return () => { seed |= 0; seed = seed + 0x6D2B79F5 | 0; let q = Math.imul(seed ^ seed >>> 15, 1 | seed); q = q + Math.imul(q ^ q >>> 7, 61 | q) ^ q; return ((q ^ q >>> 14) >>> 0) / 4294967296; };
}
function ridge(r, n, base, amp) {
  const o = [0, r() * 6.28, r() * 6.28, r() * 6.28];
  const pts = [];
  for (let i = 0; i <= n; i++) {
    const u = i / n;
    pts.push(base - amp * (0.55 * Math.sin(u * 4.1 + o[1]) + 0.3 * Math.sin(u * 9.7 + o[2]) + 0.15 * Math.sin(u * 23 + o[3])));
  }
  return pts;
}
function ridgeAt(pts, x) {
  const u = Math.min(1, Math.max(0, x / W)) * (pts.length - 1), i = Math.floor(u), f = u - i;
  return (pts[i] * (1 - f) + pts[Math.min(pts.length - 1, i + 1)] * f) * H;
}

function build() {
  const r = rng(7);
  C = { sky: rgb('--fxw-flare-sky'), dusk: rgb('--fxw-flare-dusk'), land: rgb('--fxw-flare-land'), sun: rgb('--fxw-flare-sun') };
  far = ridge(r, 64, 0.6, 0.075);
  near = ridge(r, 64, 0.7, 0.065);
}

// Aperture outline: an N-gon whose sides bow out to a circle as the blades open.
function iris(x, y, R, n, rot, round) {
  const p = new Path2D();
  const seg = (Math.PI * 2) / n, apo = Math.cos(Math.PI / n);
  for (let k = 0; k <= 72; k++) {
    const a = (k / 72) * Math.PI * 2;
    const local = ((a - rot) % seg + seg) % seg - seg / 2;
    const poly = apo / Math.cos(local);
    const rr = R * (poly + (1 - poly) * round);
    const px = x + Math.cos(a) * rr, py = y + Math.sin(a) * rr;
    k ? p.lineTo(px, py) : p.moveTo(px, py);
  }
  p.closePath();
  return p;
}

function coverage(sx, sy, rad) {
  // Sample the sun's disc and count how much sits above both ridgelines.
  let open = 0, all = 0;
  for (let i = -3; i <= 3; i++) for (let j = -3; j <= 3; j++) {
    if (i * i + j * j > 10) continue;
    const px = sx + (i / 3) * rad, py = sy + (j / 3) * rad;
    all++;
    if (py < ridgeAt(far, px) && py < ridgeAt(near, px)) open++;
  }
  return open / all;
}

function draw() {
  if (!W || !C) return;
  const N = STOPS[stop];
  const open = 1 - stop / 7;                    // 1 wide open … 0 stopped right down
  const round = Math.pow(open, 1.4);            // blades curve away to a circle wide open
  const sx = sun.x * W, sy = sun.y * H, cx = W / 2, cy = H / 2;
  const D = Math.hypot(W, H);
  const sunR = Math.max(5, D * 0.012);
  vis = coverage(sx, sy, sunR);
  const rot = 0.26 + (blades === 6 ? 0 : blades === 9 ? 0.12 : 0.05);

  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  ctx.globalCompositeOperation = 'source-over'; ctx.globalAlpha = 1;
  let g = ctx.createLinearGradient(0, 0, 0, H * 0.66);
  g.addColorStop(0, css(C.sky)); g.addColorStop(0.55, css(mix(C.sky, C.dusk, 0.55))); g.addColorStop(1, css(C.dusk));
  ctx.fillStyle = g; ctx.fillRect(0, 0, W, H);
  // warm scattering around the sun, present even when it is behind the hill
  g = ctx.createRadialGradient(sx, sy, 0, sx, sy, D * 0.45);
  g.addColorStop(0, css(mix(C.dusk, C.sun, 0.6), 0.75)); g.addColorStop(0.3, css(C.dusk, 0.28)); g.addColorStop(1, css(C.dusk, 0));
  ctx.fillStyle = g; ctx.fillRect(0, 0, W, H);

  // the sun itself sits behind the hills
  ctx.globalCompositeOperation = 'lighter';
  g = ctx.createRadialGradient(sx, sy, 0, sx, sy, sunR * 4.5);
  g.addColorStop(0, css(C.sun)); g.addColorStop(0.22, css(C.sun, 0.95)); g.addColorStop(0.3, css(C.sun, 0.35)); g.addColorStop(1, css(C.sun, 0));
  ctx.fillStyle = g; ctx.fillRect(sx - sunR * 5, sy - sunR * 5, sunR * 10, sunR * 10);
  ctx.globalCompositeOperation = 'source-over';

  const hill = (pts, col) => {
    ctx.beginPath(); ctx.moveTo(0, H);
    pts.forEach((v, i) => ctx.lineTo((i / (pts.length - 1)) * W, v * H));
    ctx.lineTo(W, H); ctx.closePath(); ctx.fillStyle = col; ctx.fill();
  };
  hill(far, css(mix(C.land, C.dusk, 0.38)));
  hill(near, css(C.land));

  if (vis <= 0.001) return;
  ctx.globalCompositeOperation = 'lighter';

  // veiling glare: low-contrast wash, strongest toward the sun
  g = ctx.createRadialGradient(sx, sy, 0, sx, sy, D * 0.8);
  g.addColorStop(0, css(C.sun, 0.22 * vis)); g.addColorStop(1, css(C.sun, 0));
  ctx.fillStyle = g; ctx.fillRect(0, 0, W, H);

  // core bloom over the hill edge
  g = ctx.createRadialGradient(sx, sy, 0, sx, sy, sunR * 5.5);
  g.addColorStop(0, css(C.sun, vis)); g.addColorStop(0.16, css(C.sun, 0.6 * vis)); g.addColorStop(1, css(C.sun, 0));
  ctx.fillStyle = g; ctx.fillRect(sx - sunR * 6, sy - sunR * 6, sunR * 12, sunR * 12);

  // Diffraction star: each straight blade edge throws a pair of opposed spikes.
  // Even blade counts overlap their pairs (N spikes); odd counts cannot (2N spikes).
  const spikes = blades % 2 ? blades * 2 : blades;
  const sLen = D * (0.06 + 0.34 * Math.pow(1 - open, 1.3)) * vis;
  const sAlpha = (0.15 + 0.6 * (1 - open)) * vis * (1 - round * 0.9);
  if (sAlpha > 0.01) {
    for (let k = 0; k < spikes; k++) {
      const a = rot + (k / spikes) * Math.PI * 2 + Math.PI / blades / 2;
      const len = sLen * (k % 2 ? 0.82 : 1);
      const ex = sx + Math.cos(a) * len, ey = sy + Math.sin(a) * len;
      const nx = -Math.sin(a), ny = Math.cos(a), w = Math.max(1, sunR * 0.28);
      g = ctx.createLinearGradient(sx, sy, ex, ey);
      g.addColorStop(0, css(C.sun, sAlpha)); g.addColorStop(0.35, css(mix(C.sun, [255, 190, 140], 0.4), sAlpha * 0.45)); g.addColorStop(1, css([150, 190, 255], 0));
      ctx.fillStyle = g;
      ctx.beginPath();
      ctx.moveTo(sx + nx * w, sy + ny * w);
      ctx.lineTo(ex, ey);
      ctx.lineTo(sx - nx * w, sy - ny * w);
      ctx.closePath();
      ctx.fill();
    }
  }

  // Ghosts: images of the aperture, so they share its shape, and shrink as it closes.
  const scale = Math.pow(STOPS[0] / N, 0.42);
  const gain = (0.65 + 0.35 * (1 - open)) * vis;
  for (const gh of GHOSTS) {
    const gx = cx + (sx - cx) * gh.t, gy = cy + (sy - cy) * gh.t;
    const R = D * gh.r * scale;
    // three passes at slightly different scales split the rim into colour, like real dispersion
    [[1, [255, 90, 70]], [1.035, [90, 255, 120]], [1.07, [80, 130, 255]]].forEach(([sc, ch]) => {
      const col = mix(gh.tint, ch, 0.55);
      const path = iris(gx, gy, R * sc, blades, rot, round);
      const rg = ctx.createRadialGradient(gx, gy, 0, gx, gy, R * sc);
      rg.addColorStop(0, css(col, gh.a * 0.25 * gain));
      rg.addColorStop(0.82, css(col, gh.a * 0.55 * gain));
      rg.addColorStop(1, css(col, gh.a * 1.1 * gain));
      ctx.fillStyle = rg; ctx.fill(path);
    });
  }
  // the faint iris ring (circular reflection between the two rear elements)
  const rx = cx + (sx - cx) * -0.05, ry = cy + (sy - cy) * -0.05;
  g = ctx.createRadialGradient(rx, ry, D * 0.27, rx, ry, D * 0.31);
  g.addColorStop(0, css([255, 200, 160], 0)); g.addColorStop(0.45, css([255, 214, 170], 0.035 * vis));
  g.addColorStop(0.6, css([170, 220, 255], 0.03 * vis)); g.addColorStop(1, css([170, 220, 255], 0));
  ctx.fillStyle = g; ctx.fillRect(0, 0, W, H);
  ctx.globalCompositeOperation = 'source-over';
}

function readout() {
  const N = STOPS[stop];
  const spikes = blades % 2 ? blades * 2 : blades;
  out.f.textContent = 'f/' + N;
  out.blades.textContent = blades;
  out.star.textContent = stop === 0 ? 'round iris' : spikes + '-point star';
  apIn.setAttribute('aria-valuetext', 'f/' + N);
}
let shownClear = -1;
function clearOut() {
  const c = Math.round(vis * 100);
  if (c !== shownClear) { shownClear = c; out.clear.textContent = c; }
}

function frame(now) {
  if (!root.isConnected) { io.disconnect(); ro.disconnect(); return; }
  raf = 0;
  if (!visible) return;
  if (document.hidden) { raf = requestAnimationFrame(frame); return; }
  const dt = Math.min(0.05, Math.max(0.001, (now - last) / 1000)); last = now;
  const calm = calmQ.matches;
  if (!calm && !dragging && now - userAt > 5000) {
    // left alone, the sun idles along a shallow arc so the ghosts swing through centre
    t += dt;
    sun.tx = 0.5 + 0.3 * Math.sin(t * 0.12 + 0.9);
    sun.ty = 0.5 - 0.2 * Math.cos(t * 0.12 + 0.9) + 0.02;
  }
  const k = calm ? 1 : 1 - Math.exp(-dt / 0.08);
  sun.x += (sun.tx - sun.x) * k; sun.y += (sun.ty - sun.y) * k;
  root.style.setProperty('--fxw-flare-x', sun.x.toFixed(4));
  root.style.setProperty('--fxw-flare-y', sun.y.toFixed(4));
  draw();
  clearOut();
  const moving = Math.abs(sun.tx - sun.x) + Math.abs(sun.ty - sun.y) > 0.0004;
  if (!calm || moving || dragging) raf = requestAnimationFrame(frame);
}
function kick() { if (!raf && visible) { last = performance.now(); raf = requestAnimationFrame(frame); } }

function aim(x, y) {
  sun.tx = Math.min(0.97, Math.max(0.03, x));
  sun.ty = Math.min(0.9, Math.max(0.04, y));
  userAt = performance.now();
  kick();
}
function fromEvent(e) {
  const r = root.getBoundingClientRect();
  aim((e.clientX - r.left) / r.width, (e.clientY - r.top) / r.height);
}
root.addEventListener('pointerdown', (e) => {
  if (e.button !== 0 || e.target.closest('.fxw-flare__panel')) return;
  dragging = true;
  root.setPointerCapture(e.pointerId);
  fromEvent(e);
  e.preventDefault();
});
root.addEventListener('pointermove', (e) => { if (dragging) fromEvent(e); });
root.addEventListener('pointerup', () => { dragging = false; });
root.addEventListener('pointercancel', () => { dragging = false; });
sunBtn.addEventListener('keydown', (e) => {
  const d = e.shiftKey ? 0.08 : 0.025;
  const m = { ArrowLeft: [-d, 0], ArrowRight: [d, 0], ArrowUp: [0, -d], ArrowDown: [0, d] }[e.key];
  if (!m) return;
  e.preventDefault();
  aim(sun.tx + m[0], sun.ty + m[1]);
  clearTimeout(sunBtn._t);
  sunBtn._t = setTimeout(() => { if (root.isConnected) sr.textContent = 'Sun ' + Math.round(vis * 100) + ' percent clear of the hills'; }, 500);
});
apIn.addEventListener('input', () => { stop = +apIn.value; readout(); userAt = performance.now(); kick(); if (calmQ.matches) draw(); });
radios.forEach((r) => r.addEventListener('change', () => { blades = +r.value; readout(); userAt = performance.now(); kick(); if (calmQ.matches) draw(); }));

const ro = new ResizeObserver(() => {
  if (!root.isConnected) { ro.disconnect(); return; }
  const r = cv.getBoundingClientRect();
  if (!r.width || !r.height) return;
  dpr = Math.min(2, devicePixelRatio || 1);
  W = r.width; H = r.height;
  cv.width = Math.round(W * dpr); cv.height = Math.round(H * dpr);
  if (!C) build();
  draw(); clearOut();
});
ro.observe(cv);
const io = new IntersectionObserver((entries) => {
  if (!root.isConnected) { io.disconnect(); return; }
  visible = entries[entries.length - 1].isIntersecting;
  if (visible) kick();
});
io.observe(root);
calmQ.addEventListener?.('change', () => { if (root.isConnected) { draw(); kick(); } });
readout();

css:
.fxw-fireflies {
  /* Re-theme with these four: night sky, meadow, the bioluminescence, and the lantern. */
  --fxw-fireflies-night: oklch(0.18 0.03 175);
  --fxw-fireflies-grass: oklch(0.13 0.025 150);
  --fxw-fireflies-glow: oklch(0.93 0.2 120);
  --fxw-fireflies-lamp: oklch(0.84 0.14 68);

  --fxw-fireflies-ink: color-mix(in oklch, var(--fxw-fireflies-glow) 18%, oklch(0.97 0.01 110));
  --fxw-fireflies-muted: color-mix(in oklch, var(--fxw-fireflies-ink) 58%, var(--fxw-fireflies-night));
  --fxw-fireflies-chip: color-mix(in oklch, var(--fxw-fireflies-grass) 70%, transparent);
  --fxw-fireflies-rule: color-mix(in oklch, var(--fxw-fireflies-ink) 14%, transparent);
  --fxw-fireflies-out: cubic-bezier(.16, 1, .3, 1);
  --fxw-fireflies-mono: ui-monospace, Menlo, Consolas, monospace;

  container-type: inline-size;
  position: relative;
  isolation: isolate;
  overflow: clip;
  box-sizing: border-box;
  inline-size: 100%;
  aspect-ratio: 4 / 3.2;
  min-block-size: 220px;
  max-block-size: 380px;
  display: grid;
  grid-template-areas: "head" "." "panel";
  grid-template-rows: auto 1fr auto;
  padding: clamp(10px, 3.4%, 16px);
  border-radius: 16px;
  color: var(--fxw-fireflies-ink);
  background: linear-gradient(var(--fxw-fireflies-night), var(--fxw-fireflies-grass));
  font: 500 12px/1.3 system-ui, -apple-system, "Segoe UI", sans-serif;
  -webkit-font-smoothing: antialiased;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(p, figure) { margin: 0; }

  & .fxw-fireflies__canvas { position: absolute; inset: 0; inline-size: 100%; block-size: 100%; display: block; }
  & .fxw-fireflies__stage {
    position: absolute;
    inset: 0;
    cursor: crosshair;
    touch-action: manipulation;
    border-radius: inherit;
    &:focus-visible { outline: 2px solid var(--fxw-fireflies-glow); outline-offset: -4px; }
  }

  & .fxw-fireflies__head {
    grid-area: head;
    position: relative;
    display: grid;
    grid-template-columns: 1fr auto;
    align-items: start;
    gap: 10px;
    pointer-events: none;
  }
  & .fxw-fireflies__title {
    font-weight: 700;
    font-size: clamp(14px, 4.6cqi, 18px);
    letter-spacing: -.01em;
    text-wrap: balance;
    text-shadow: 0 1px 10px var(--fxw-fireflies-night);
  }
  & .fxw-fireflies__sub {
    font: 500 10px/1.3 var(--fxw-fireflies-mono);
    letter-spacing: .06em;
    text-transform: uppercase;
    color: var(--fxw-fireflies-muted);
    font-variant-numeric: tabular-nums;
  }

  & .fxw-fireflies__sync {
    display: grid;
    grid-template-columns: auto auto;
    grid-template-areas: "cap val" "spark spark";
    align-items: baseline;
    gap: 2px 8px;
    padding: 7px 10px 8px;
    border-radius: 11px;
    background: var(--fxw-fireflies-chip);
    backdrop-filter: blur(8px);
    box-shadow: 0 0 0 1px var(--fxw-fireflies-rule);
    min-inline-size: 118px;
    transition: box-shadow .6s var(--fxw-fireflies-out);
    & figcaption {
      grid-area: cap;
      font: 600 9.5px/1 var(--fxw-fireflies-mono);
      letter-spacing: .08em;
      text-transform: uppercase;
      color: var(--fxw-fireflies-muted);
      & i { font-family: ui-serif, Georgia, serif; text-transform: none; font-size: 1.25em; letter-spacing: 0; }
    }
    & svg {
      grid-area: spark;
      inline-size: 100%;
      block-size: 22px;
      overflow: visible;
      & line { stroke: var(--fxw-fireflies-rule); stroke-dasharray: 2 3; vector-effect: non-scaling-stroke; }
      & polyline { fill: none; stroke: var(--fxw-fireflies-glow); stroke-width: 1.5; stroke-linejoin: round; vector-effect: non-scaling-stroke; }
    }
  }
  & .fxw-fireflies__r {
    grid-area: val;
    justify-self: end;
    font: 700 clamp(16px, 5.4cqi, 21px)/1 var(--fxw-fireflies-mono);
    font-variant-numeric: tabular-nums;
    letter-spacing: -.02em;
  }
  /* In step: the readout picks up the glow it is measuring. */
  &[data-synced] .fxw-fireflies__sync { box-shadow: 0 0 0 1px color-mix(in oklch, var(--fxw-fireflies-glow) 50%, transparent), 0 0 22px -4px color-mix(in oklch, var(--fxw-fireflies-glow) 50%, transparent); }
  &[data-synced] .fxw-fireflies__r { color: var(--fxw-fireflies-glow); }

  & .fxw-fireflies__panel {
    grid-area: panel;
    position: relative;
    display: grid;
    grid-template-columns: 1fr auto;
    align-items: center;
    gap: 12px;
    padding: 8px 8px 8px 12px;
    border-radius: 12px;
    background: var(--fxw-fireflies-chip);
    backdrop-filter: blur(8px);
    box-shadow: 0 0 0 1px var(--fxw-fireflies-rule);
  }
  & .fxw-fireflies__k {
    display: grid;
    grid-template-columns: auto 1fr;
    align-items: center;
    gap: 10px;
    min-inline-size: 0;
    font: 500 10.5px/1 var(--fxw-fireflies-mono);
    letter-spacing: .04em;
    text-transform: uppercase;
    color: var(--fxw-fireflies-muted);
    font-variant-numeric: tabular-nums;
    & b { color: var(--fxw-fireflies-ink); font-weight: 700; }
    & i { font: italic 400 1.3em/1 ui-serif, Georgia, serif; text-transform: none; color: var(--fxw-fireflies-ink); }
    & input {
      inline-size: 100%; min-inline-size: 50px; margin: 0;
      accent-color: var(--fxw-fireflies-glow);
      cursor: pointer;
      &:focus-visible { outline: 2px solid var(--fxw-fireflies-glow); outline-offset: 3px; border-radius: 4px; }
    }
  }
  & .fxw-fireflies__scatter {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 7px 11px 7px 9px;
    border: 1px solid var(--fxw-fireflies-rule);
    border-radius: 999px;
    background: color-mix(in oklch, var(--fxw-fireflies-ink) 6%, transparent);
    color: var(--fxw-fireflies-ink);
    font: 600 11px/1 system-ui, sans-serif;
    letter-spacing: .02em;
    cursor: pointer;
    transition: background-color .25s var(--fxw-fireflies-out), border-color .25s var(--fxw-fireflies-out), scale .3s var(--fxw-fireflies-out);
    & svg { inline-size: 15px; block-size: 15px; fill: none; stroke: currentColor; stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; }
    &:hover { background: color-mix(in oklch, var(--fxw-fireflies-ink) 12%, transparent); border-color: color-mix(in oklch, var(--fxw-fireflies-ink) 30%, transparent); }
    &:active { scale: .96; }
    &:focus-visible { outline: 2px solid var(--fxw-fireflies-glow); outline-offset: 2px; }
  }
  & .fxw-fireflies__sr {
    position: absolute; inline-size: 1px; block-size: 1px; overflow: hidden;
    clip-path: inset(50%); white-space: nowrap;
  }

  @container (max-width: 330px) {
    & .fxw-fireflies__sub { display: none; }
    & .fxw-fireflies__k { gap: 8px; }
    & .fxw-fireflies__word { position: absolute; inline-size: 1px; block-size: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
  }
}

@media (prefers-reduced-motion: reduce) {
  .fxw-fireflies .fxw-fireflies__sync,
  .fxw-fireflies .fxw-fireflies__scatter { transition: none; }
}

js:
const calmQ = matchMedia('(prefers-reduced-motion: reduce)');
const cv = root.querySelector('.fxw-fireflies__canvas');
const ctx = cv.getContext('2d');
const stage = root.querySelector('.fxw-fireflies__stage');
const kIn = root.querySelector('.fxw-fireflies__k input');
const outEps = root.querySelector('[data-eps]');
const outR = root.querySelector('[data-r]');
const outN = root.querySelector('[data-n]');
const spark = root.querySelector('.fxw-fireflies__sync polyline');
const scatterBtn = root.querySelector('.fxw-fireflies__scatter');
const sr = root.querySelector('.fxw-fireflies__sr');

const mk = () => { const c = document.createElement('canvas'); return [c, c.getContext('2d')]; };
const [bg, bctx] = mk();
const [dot, dctx] = mk();
const [probe] = mk();
const pctx = probe.getContext('2d', { willReadFrequently: true });
probe.width = probe.height = 1;
function rgb(name) {
  pctx.clearRect(0, 0, 1, 1);
  pctx.fillStyle = '#888';
  pctx.fillStyle = getComputedStyle(root).getPropertyValue(name).trim() || '#888';
  pctx.fillRect(0, 0, 1, 1);
  const d = pctx.getImageData(0, 0, 1, 1).data;
  return [d[0], d[1], d[2]];
}
const mix = (a, b, t) => a.map((v, i) => Math.round(v + (b[i] - v) * t));
const css = (c, a = 1) => 'rgb(' + c[0] + ' ' + c[1] + ' ' + c[2] + ' / ' + a + ')';
function rng(seed) {
  return () => { seed |= 0; seed = seed + 0x6D2B79F5 | 0; let q = Math.imul(seed ^ seed >>> 15, 1 | seed); q = q + Math.imul(q ^ q >>> 7, 61 | q) ^ q; return ((q ^ q >>> 14) >>> 0) / 4294967296; };
}

// Mirollo–Strogatz: each flasher charges along a concave state curve x = f(φ).
// A seen flash adds ε to x, so the nearer a firefly is to firing, the larger its phase jump.
const B = 2;
const EB = Math.exp(B) - 1;
const f = (p) => Math.log(1 + EB * p) / B;
const finv = (x) => (Math.exp(B * x) - 1) / EB;
const SIGHT = 0.25;            // how far a flash is seen, as a fraction of the meadow's width

let W = 0, H = 0, dpr = 1, C = null, flies = [], bursts = [];
let eps = 0.008, time = 0, rS = 0, hist = [], lastTick = 0, visible = false, raf = 0, last = 0, synced = false;

function seed() {
  const r = rng(1931);
  const n = Math.round(Math.min(110, Math.max(56, W * H / 1500)));
  flies = [];
  for (let i = 0; i < n; i++) {
    const inTrees = r() < 0.18;
    flies.push({
      hx: 0.03 + r() * 0.94,
      hy: inTrees ? 0.3 + r() * 0.12 : 0.45 + Math.pow(r(), 0.8) * 0.42,
      a1: r() * 6.28, a2: r() * 6.28, w1: 0.12 + r() * 0.2, w2: 0.15 + r() * 0.25,
      ph: r(), T: 1.05 * (1 + (r() + r() + r() - 1.5) * 0.05),
      fired: -9, ref: -9, x: 0, y: 0, z: inTrees ? 0.6 : 0.75 + r() * 0.5
    });
  }
  outN.textContent = n;
}

function paintBackground() {
  const r = rng(77);
  bg.width = Math.round(W * dpr); bg.height = Math.round(H * dpr);
  const b = bctx;
  b.setTransform(dpr, 0, 0, dpr, 0, 0);
  let g = b.createLinearGradient(0, 0, 0, H);
  g.addColorStop(0, css(C.night)); g.addColorStop(0.34, css(mix(C.night, C.lamp, 0.1)));
  g.addColorStop(0.42, css(mix(C.night, C.grass, 0.6))); g.addColorStop(1, css(C.grass));
  b.fillStyle = g; b.fillRect(0, 0, W, H);
  for (let i = 0; i < 46; i++) {
    b.fillStyle = css([235, 240, 225], 0.15 + r() * 0.45);
    const s = r() < 0.15 ? 1.4 : 0.8;
    b.fillRect(r() * W, r() * H * 0.33, s, s);
  }
  // treeline: overlapping crowns along the far edge of the meadow
  // treeline: many overlapping crowns on a wandering skyline, with the odd spire of a fir
  b.fillStyle = css(mix(C.grass, [0, 0, 0], 0.25));
  b.fillRect(0, H * 0.4, W, H * 0.6);
  const p1 = r() * 6, p2 = r() * 6, u = H / 300;
  for (let x = -8; x < W + 8; x += 3 + r() * 5) {
    const top = H * 0.4 - (14 + 9 * Math.sin(x * 0.021 + p1) + 5 * Math.sin(x * 0.067 + p2)) * u;
    if (r() < 0.07) {
      const h = (22 + r() * 22) * u, w = (5 + r() * 4) * u;
      b.beginPath(); b.moveTo(x - w, top + 6 * u); b.lineTo(x, top - h); b.lineTo(x + w, top + 6 * u); b.fill();
    }
    const rad = (5 + r() * 9) * u;
    b.beginPath(); b.arc(x, top + rad * 0.6 + r() * 6 * u, rad, 0, 6.2832); b.fill();
    b.fillRect(x - rad, top + rad * 0.6, rad * 2, H * 0.42 - top);
  }
  g = b.createLinearGradient(0, H * 0.42, 0, H);
  g.addColorStop(0, css(mix(C.grass, [0, 0, 0], 0.25))); g.addColorStop(0.14, css(mix(C.grass, C.night, 0.35)));
  g.addColorStop(1, css(mix(C.grass, [0, 0, 0], 0.3)));
  b.fillStyle = g; b.fillRect(0, H * 0.42, W, H * 0.58);
  // grass heads, densest at the front
  b.lineCap = 'round';
  for (let i = 0; i < W * 1.4; i++) {
    const gx = r() * W, gy = H * (0.6 + Math.pow(r(), 0.6) * 0.42), h = 6 + r() * 22 * (gy / H);
    b.strokeStyle = css(mix(C.grass, [0, 0, 0], 0.35 + r() * 0.3), 0.9);
    b.lineWidth = 0.6 + r() * 0.9;
    b.beginPath(); b.moveTo(gx, gy); b.quadraticCurveTo(gx + (r() - 0.5) * 6, gy - h * 0.6, gx + (r() - 0.5) * 10, gy - h); b.stroke();
  }
  // a soft glow sprite, painted once in the bioluminescent colour
  dot.width = dot.height = 64;
  g = dctx.createRadialGradient(32, 32, 0, 32, 32, 32);
  g.addColorStop(0, css(mix(C.glow, [255, 255, 255], 0.55))); g.addColorStop(0.12, css(C.glow, 0.9));
  g.addColorStop(0.35, css(C.glow, 0.28)); g.addColorStop(1, css(C.glow, 0));
  dctx.clearRect(0, 0, 64, 64); dctx.fillStyle = g; dctx.fillRect(0, 0, 64, 64);
}

function fire(i, q, fired) {
  const F = flies[i];
  fired.add(i);
  F.ph = 0; F.fired = time; F.ref = time + 0.12 * F.T;
  for (let j = 0; j < flies.length; j++) {
    if (fired.has(j)) continue;
    const G = flies[j];
    if (time < G.ref) continue;
    const d = Math.hypot((G.x - F.x) * W, (G.y - F.y) * H) / W;
    if (d > SIGHT) continue;
    const x = f(G.ph) + eps * (1 - 0.5 * d / SIGHT);
    if (x >= 1) q.push(j); else G.ph = finv(x);
  }
}

function step(dt) {
  time += dt;
  const q = [];
  for (let i = 0; i < flies.length; i++) {
    const F = flies[i];
    F.ph += dt / F.T;
    if (F.ph >= 1) q.push(i);
    F.x = F.hx + 0.035 * Math.sin(time * F.w1 + F.a1);
    F.y = F.hy + 0.025 * Math.sin(time * F.w2 + F.a2);
  }
  // absorption: anyone pushed over threshold fires in the same instant and joins the group
  const fired = new Set();
  while (q.length) { const i = q.pop(); if (!fired.has(i)) fire(i, q, fired); }
  let re = 0, im = 0;
  for (const F of flies) { re += Math.cos(F.ph * 6.2832); im += Math.sin(F.ph * 6.2832); }
  const r = Math.hypot(re, im) / flies.length;
  rS += (r - rS) * (1 - Math.exp(-dt / 0.8));
}

function lantern(px, py) {
  // a lantern is one more flasher, brighter and seen further
  bursts.push({ x: px, y: py, t0: time });
  for (const G of flies) {
    if (time < G.ref) continue;
    const d = Math.hypot((G.x - px) * W, (G.y - py) * H) / W;
    if (d > SIGHT * 1.4) continue;
    const x = f(G.ph) + 0.4 * (1 - 0.6 * d / (SIGHT * 1.4));
    G.ph = x >= 1 ? 0 : finv(x);
    if (x >= 1) { G.fired = time; G.ref = time + 0.12 * G.T; }
  }
  if (calmQ.matches) draw();
}

function draw() {
  if (!W) return;
  const calm = calmQ.matches;
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  ctx.globalCompositeOperation = 'source-over'; ctx.globalAlpha = 1;
  ctx.drawImage(bg, 0, 0, W, H);
  ctx.globalCompositeOperation = 'lighter';
  let amb = 0;
  for (const F of flies) {
    const age = time - F.fired;
    // flash envelope: 50 ms rise, 160 ms decay — a cold light, no afterglow
    const glow = calm ? 0.42 : age < 0.05 ? age / 0.05 : Math.exp(-(age - 0.05) / 0.16);
    const px = F.x * W, py = (F.y - (calm ? 0 : Math.min(age, 0.4) * 0.03)) * H;
    if (glow > 0.015) {
      const s = (8 + 30 * glow) * F.z;
      ctx.globalAlpha = Math.min(1, glow);
      ctx.drawImage(dot, px - s / 2, py - s / 2, s, s);
      amb += glow;
    } else {
      ctx.globalAlpha = 0.3;
      ctx.drawImage(dot, px - 3, py - 3, 6, 6);
    }
  }
  // the meadow itself brightens when they flash together
  amb /= flies.length;
  if (amb > 0.01) {
    const g = ctx.createLinearGradient(0, H * 0.4, 0, H);
    g.addColorStop(0, css(C.glow, 0)); g.addColorStop(0.5, css(C.glow, Math.min(0.22, amb * 0.3))); g.addColorStop(1, css(C.glow, Math.min(0.1, amb * 0.12)));
    ctx.globalAlpha = 1; ctx.fillStyle = g; ctx.fillRect(0, H * 0.4, W, H * 0.6);
  }
  bursts = bursts.filter((b) => time - b.t0 < 0.9);
  for (const b of bursts) {
    const k = (time - b.t0) / 0.9, x = b.x * W, y = b.y * H;
    const g = ctx.createRadialGradient(x, y, 0, x, y, 30 + 40 * k);
    g.addColorStop(0, css(C.lamp, (1 - k) * 0.9)); g.addColorStop(1, css(C.lamp, 0));
    ctx.globalAlpha = 1; ctx.fillStyle = g; ctx.fillRect(x - 80, y - 80, 160, 160);
    if (!calm) {
      ctx.strokeStyle = css(C.lamp, (1 - k) * 0.5); ctx.lineWidth = 1.2;
      ctx.beginPath(); ctx.arc(x, y, SIGHT * 1.4 * W * (0.15 + 0.85 * (1 - Math.pow(1 - k, 3))), 0, 6.2832); ctx.stroke();
    }
  }
  ctx.globalCompositeOperation = 'source-over'; ctx.globalAlpha = 1;
}

function report() {
  outR.textContent = rS.toFixed(2);
  hist.push(rS);
  if (hist.length > 120) hist.shift();
  spark.setAttribute('points', hist.map((v, i) => ((i / 119) * 100).toFixed(1) + ',' + (22 - v * 22).toFixed(1)).join(' '));
  const now = rS > (synced ? 0.72 : 0.8);
  if (now !== synced) {
    synced = now;
    root.toggleAttribute('data-synced', synced);
    sr.textContent = synced ? 'The meadow is flashing in step.' : 'The flashes have drifted apart.';
  }
}

function frame(now) {
  if (!root.isConnected) { io.disconnect(); ro.disconnect(); return; }
  raf = 0;
  if (!visible) return;
  raf = requestAnimationFrame(frame);
  if (document.hidden || !W) return;
  const dt = Math.min(0.05, Math.max(0.001, (now - last) / 1000)); last = now;
  step(dt);
  if (!calmQ.matches) draw();
  if (now - lastTick > 250) { lastTick = now; report(); }
}
function kick() { if (!raf && visible) { last = performance.now(); raf = requestAnimationFrame(frame); } }

stage.addEventListener('pointerdown', (e) => {
  const r = root.getBoundingClientRect();
  lantern((e.clientX - r.left) / r.width, (e.clientY - r.top) / r.height);
});
stage.addEventListener('keydown', (e) => {
  if (e.key !== 'Enter' && e.key !== ' ') return;
  e.preventDefault();
  lantern(0.5, 0.62);
});
kIn.addEventListener('input', () => { eps = +kIn.value; outEps.textContent = eps.toFixed(3); });
scatterBtn.addEventListener('click', () => {
  for (const F of flies) F.ph = Math.random();
  sr.textContent = 'Phases scattered.';
  if (calmQ.matches) draw();
});

const ro = new ResizeObserver(() => {
  if (!root.isConnected) { ro.disconnect(); return; }
  const r = cv.getBoundingClientRect();
  if (!r.width || !r.height) return;
  dpr = Math.min(2, devicePixelRatio || 1);
  W = r.width; H = r.height;
  cv.width = Math.round(W * dpr); cv.height = Math.round(H * dpr);
  C = { night: rgb('--fxw-fireflies-night'), grass: rgb('--fxw-fireflies-grass'), glow: rgb('--fxw-fireflies-glow'), lamp: rgb('--fxw-fireflies-lamp') };
  if (!flies.length) { seed(); step(0); }
  paintBackground();
  draw();
});
ro.observe(cv);
const io = new IntersectionObserver((entries) => {
  if (!root.isConnected) { io.disconnect(); return; }
  visible = entries[entries.length - 1].isIntersecting;
  if (visible) kick();
});
io.observe(root);
calmQ.addEventListener?.('change', () => { if (root.isConnected) draw(); });

css:
@property --fxw-filament-lvl {
  syntax: "<number>";
  inherits: true;
  initial-value: 0.72;
}

.fxw-filament {
  /* Re-theme with these four. The glow colour is computed from the filament temperature, not themed. */
  --fxw-filament-wall: oklch(0.885 0.018 78);
  --fxw-filament-ink: oklch(0.27 0.025 60);
  --fxw-filament-brass: oklch(0.74 0.105 78);
  --fxw-filament-cord: oklch(0.33 0.03 40);

  --fxw-filament-c: rgb(255 170 90);
  --fxw-filament-b: 0.6;
  --fxw-filament-muted: color-mix(in oklch, var(--fxw-filament-ink) 58%, var(--fxw-filament-wall));
  --fxw-filament-rule: color-mix(in oklch, var(--fxw-filament-ink) 14%, transparent);
  --fxw-filament-brass-hi: color-mix(in oklch, var(--fxw-filament-brass) 55%, white);
  --fxw-filament-brass-lo: color-mix(in oklch, var(--fxw-filament-brass) 62%, var(--fxw-filament-ink));
  --fxw-filament-out: cubic-bezier(.16, 1, .3, 1);
  --fxw-filament-spring: linear(0, 0.22 7%, 0.7 18%, 1.01 29%, 1.09 37%, 1.07 46%, 1.01 60%, 0.995 75%, 1);
  --fxw-filament-mono: ui-monospace, Menlo, Consolas, monospace;

  container-type: inline-size;
  position: relative;
  isolation: isolate;
  overflow: clip;
  box-sizing: border-box;
  inline-size: 100%;
  aspect-ratio: 5 / 4;
  min-block-size: 236px;
  max-block-size: 380px;
  border-radius: 16px;
  color: var(--fxw-filament-ink);
  background:
    radial-gradient(120% 90% at 30% 20%, color-mix(in oklch, var(--fxw-filament-wall) 70%, white), transparent 70%),
    var(--fxw-filament-wall);
  box-shadow: inset 0 0 0 1px var(--fxw-filament-rule);
  font: 500 12px/1.3 system-ui, -apple-system, "Segoe UI", sans-serif;
  -webkit-font-smoothing: antialiased;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(p, h3, dl, dd) { margin: 0; }

  /* Light thrown on the plaster: added, not painted over. */
  & .fxw-filament__pool {
    position: absolute;
    inline-size: 150cqi;
    aspect-ratio: 1;
    inset-inline-start: var(--fxw-filament-px, 25%);
    inset-block-start: var(--fxw-filament-py, 60%);
    translate: -50% -50%;
    border-radius: 50%;
    pointer-events: none;
    mix-blend-mode: plus-lighter;
    opacity: calc(var(--fxw-filament-b) * .62);
    background: radial-gradient(closest-side, var(--fxw-filament-c), color-mix(in srgb, var(--fxw-filament-c) 42%, transparent) 16%, color-mix(in srgb, var(--fxw-filament-c) 12%, transparent) 46%, transparent);
  }

  & .fxw-filament__lamp {
    position: absolute;
    inset-block: 0;
    inset-inline-start: 2%;
    inline-size: 40%;
    & svg {
      display: block; inline-size: 100%; block-size: 100%; overflow: visible;
      transform-origin: 50% 0;
      animation: fxw-filament-sway 2.6s cubic-bezier(.37, 0, .63, 1) infinite alternate;
    }
  }
  & .fxw-filament__cord { stroke: var(--fxw-filament-cord); stroke-width: 3; }
  & .fxw-filament__twist { stroke: color-mix(in oklch, var(--fxw-filament-cord) 60%, white); stroke-width: 3; stroke-dasharray: 1.2 2.2; opacity: .5; }
  & .fxw-filament__holder { fill: var(--fxw-filament-brass-lo); }
  & .fxw-filament__rings { stroke: var(--fxw-filament-brass-hi); stroke-width: .8; opacity: .6; }
  & .fxw-filament__collar { fill: var(--fxw-filament-brass); }
  & .fxw-filament__glass {
    fill: color-mix(in srgb, var(--fxw-filament-c) calc(var(--fxw-filament-b) * 30%), color-mix(in oklch, var(--fxw-filament-wall) 70%, white));
    fill-opacity: calc(.28 + var(--fxw-filament-b) * .35);
    stroke: color-mix(in oklch, var(--fxw-filament-ink) 28%, transparent);
    stroke-width: .9;
  }
  & .fxw-filament__stem { fill: color-mix(in oklch, white 40%, transparent); stroke: color-mix(in oklch, var(--fxw-filament-ink) 22%, transparent); stroke-width: .6; }
  & .fxw-filament__shine { fill: none; stroke: white; stroke-width: 2; stroke-linecap: round; opacity: .7; }
  & .fxw-filament__tip { fill: color-mix(in oklch, var(--fxw-filament-ink) 18%, transparent); }

  /* The cage: bare tungsten, then three lit passes keyed to brightness. */
  & .fxw-filament__cage {
    fill: none;
    stroke-linecap: round;
    stroke-linejoin: round;
    & .fxw-filament__wire { stroke: color-mix(in oklch, var(--fxw-filament-ink) 55%, transparent); stroke-width: .7; }
    & .fxw-filament__support { stroke: color-mix(in oklch, var(--fxw-filament-ink) 30%, transparent); stroke-width: .45; }
    & .fxw-filament__halo { stroke: var(--fxw-filament-c); stroke-width: 7; opacity: calc(var(--fxw-filament-b) * .5); filter: blur(5px); }
    & .fxw-filament__hot { stroke: var(--fxw-filament-c); stroke-width: 2.2; opacity: var(--fxw-filament-b); filter: blur(.8px); }
    & .fxw-filament__core { stroke: color-mix(in srgb, var(--fxw-filament-c) 55%, white); stroke-width: .8; opacity: var(--fxw-filament-b); }
    & [data-back] { opacity: calc(var(--fxw-filament-b) * .55); }
    & .fxw-filament__wire[data-back] { opacity: .45; }
  }

  & .fxw-filament__panel {
    position: absolute;
    inset: 0 0 0 42%;
    display: grid;
    grid-template-areas: "head" "control" "read";
    grid-template-rows: auto 1fr auto;
    gap: 8px;
    padding: clamp(12px, 4.2cqi, 18px) clamp(12px, 4.2cqi, 18px) clamp(12px, 4.2cqi, 18px) 0;
  }
  & .fxw-filament__head { grid-area: head; display: grid; gap: 2px; }
  & .fxw-filament__brand {
    font: 650 9.5px/1 var(--fxw-filament-mono);
    letter-spacing: .16em;
    text-transform: uppercase;
    color: var(--fxw-filament-muted);
  }
  & .fxw-filament__name {
    font-size: clamp(14px, 4.8cqi, 19px);
    font-weight: 700;
    letter-spacing: -.015em;
    line-height: 1.1;
    text-wrap: balance;
  }
  & .fxw-filament__spec {
    font: 500 10px/1.3 var(--fxw-filament-mono);
    letter-spacing: .03em;
    color: var(--fxw-filament-muted);
    font-variant-numeric: tabular-nums;
  }

  & .fxw-filament__control {
    grid-area: control;
    display: grid;
    grid-template-columns: auto 1fr;
    align-items: center;
    gap: clamp(8px, 3cqi, 14px);
  }

  /* The knob: a conic arc for level, a knurled brass cap that turns with it. */
  & .fxw-filament__knob {
    --fxw-filament-size: clamp(64px, 20cqi, 84px);
    position: relative;
    inline-size: var(--fxw-filament-size);
    aspect-ratio: 1;
    border-radius: 50%;
    cursor: grab;
    touch-action: none;
    user-select: none;
    -webkit-user-select: none;
    outline: none;
    transition: --fxw-filament-lvl .45s var(--fxw-filament-spring);
    &[data-drag] { transition: none; cursor: grabbing; }
    &:focus-visible { box-shadow: 0 0 0 2px var(--fxw-filament-wall), 0 0 0 4px var(--fxw-filament-ink); }
  }
  & .fxw-filament__ticks {
    position: absolute;
    inset: 0;
    border-radius: 50%;
    background: repeating-conic-gradient(from -136.5deg, var(--fxw-filament-muted) 0 3deg, transparent 3deg 27deg);
    -webkit-mask-image: radial-gradient(closest-side, transparent 88%, #000 89% 100%), conic-gradient(from -137deg, #000 0 274deg, transparent 0);
    -webkit-mask-composite: source-in;
    mask-image: radial-gradient(closest-side, transparent 88%, #000 89% 100%), conic-gradient(from -137deg, #000 0 274deg, transparent 0);
    mask-composite: intersect;
    opacity: .7;
  }
  & .fxw-filament__arc {
    position: absolute;
    inset: 13%;
    border-radius: 50%;
    background: conic-gradient(from -135deg,
      oklch(0.66 0.19 40) 0deg,
      var(--fxw-filament-brass) calc(var(--fxw-filament-lvl) * 270deg),
      color-mix(in oklch, var(--fxw-filament-ink) 12%, transparent) calc(var(--fxw-filament-lvl) * 270deg) 270deg,
      transparent 270deg);
    -webkit-mask: radial-gradient(closest-side, transparent 80%, #000 81% 100%);
    mask: radial-gradient(closest-side, transparent 80%, #000 81% 100%);
    transition: filter .4s var(--fxw-filament-out), opacity .4s var(--fxw-filament-out);
  }
  & .fxw-filament__cap {
    position: absolute;
    inset: 24%;
    border-radius: 50%;
    rotate: calc(-135deg + var(--fxw-filament-lvl) * 270deg);
    background:
      radial-gradient(circle at 35% 30%, var(--fxw-filament-brass-hi), transparent 55%),
      repeating-conic-gradient(var(--fxw-filament-brass) 0 6deg, var(--fxw-filament-brass-lo) 6deg 12deg);
    box-shadow:
      inset 0 0 0 3px color-mix(in oklch, var(--fxw-filament-brass) 85%, white),
      0 3px 6px -2px color-mix(in oklch, var(--fxw-filament-ink) 50%, transparent),
      0 1px 0 color-mix(in oklch, var(--fxw-filament-ink) 30%, transparent);
    transition: scale .25s var(--fxw-filament-spring);
    & i {
      position: absolute;
      inset-inline-start: 50%;
      inset-block-start: 10%;
      inline-size: 2.5px;
      block-size: 26%;
      translate: -50% 0;
      border-radius: 2px;
      background: var(--fxw-filament-ink);
    }
  }
  & .fxw-filament__knob:active .fxw-filament__cap { scale: .95; }
  &:not([data-on]) .fxw-filament__arc { filter: grayscale(1); opacity: .45; }

  & .fxw-filament__level {
    display: grid;
    grid-template-columns: auto 1fr;
    align-items: baseline;
    column-gap: 2px;
    font-variant-numeric: tabular-nums;
    & b { font-size: clamp(22px, 7.4cqi, 30px); font-weight: 700; letter-spacing: -.03em; line-height: 1; }
    & span { font-weight: 600; color: var(--fxw-filament-muted); }
    & em {
      grid-column: 1 / -1;
      font: 650 9.5px/1.4 var(--fxw-filament-mono);
      font-style: normal;
      letter-spacing: .12em;
      text-transform: uppercase;
      color: var(--fxw-filament-muted);
    }
  }
  &[data-on] .fxw-filament__level em { color: color-mix(in oklch, oklch(0.62 0.17 45) 85%, var(--fxw-filament-ink)); }

  & .fxw-filament__read {
    grid-area: read;
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 6px 10px;
    padding-block-start: 8px;
    border-block-start: 1px solid var(--fxw-filament-rule);
    & div { display: grid; gap: 1px; min-inline-size: 0; }
    & dt {
      font: 600 9px/1.2 var(--fxw-filament-mono);
      letter-spacing: .12em;
      text-transform: uppercase;
      color: var(--fxw-filament-muted);
    }
    & dd {
      display: flex;
      align-items: baseline;
      gap: 3px;
      font-variant-numeric: tabular-nums;
      white-space: nowrap;
      & b { font-size: clamp(13px, 4cqi, 16px); font-weight: 650; letter-spacing: -.01em; }
      & span { font-size: 10.5px; color: var(--fxw-filament-muted); font-weight: 600; }
    }
  }
  & .fxw-filament__swatch {
    align-self: center;
    inline-size: 9px;
    block-size: 9px;
    border-radius: 50%;
    background: var(--fxw-filament-c);
    box-shadow: 0 0 0 1px var(--fxw-filament-rule), 0 0 calc(var(--fxw-filament-b) * 8px) var(--fxw-filament-c);
  }
  &:not([data-on]) .fxw-filament__swatch { background: color-mix(in oklch, var(--fxw-filament-ink) 20%, var(--fxw-filament-wall)); }

  @container (max-width: 330px) {
    & .fxw-filament__spec { display: none; }
    & .fxw-filament__control { grid-template-columns: auto; justify-items: start; gap: 4px; }
    & .fxw-filament__level { grid-template-columns: auto auto 1fr; column-gap: 4px; }
    & .fxw-filament__level em { grid-column: auto; }
  }
}

/* A draught moves the pendant: a small damped-looking pendulum about the ceiling rose. */
@keyframes fxw-filament-sway {
  from { rotate: -0.5deg; }
  to { rotate: 0.5deg; }
}

@media (prefers-reduced-motion: reduce) {
  .fxw-filament .fxw-filament__lamp svg { animation: none; }
  .fxw-filament .fxw-filament__knob,
  .fxw-filament .fxw-filament__cap,
  .fxw-filament .fxw-filament__arc { transition: none; }
}

js:
const NS = 'http://www.w3.org/2000/svg';
const knob = root.querySelector('.fxw-filament__knob');
const cage = root.querySelector('.fxw-filament__cage');
const svg = root.querySelector('.fxw-filament__lamp svg');
const out = {
  level: root.querySelector('[data-level]'), state: root.querySelector('[data-state]'),
  k: root.querySelector('[data-k]'), w: root.querySelector('[data-w]'),
  lm: root.querySelector('[data-lm]'), life: root.querySelector('[data-life]')
};

// Rated point of the lamp. Every readout below is derived from these and the live filament temperature.
const T_R = 2400, P_R = 40, LM_R = 260, LIFE_R = 2000, T_AMB = 295;

// Build the squirrel cage: eight coiled strands on a cylinder, back strands drawn first.
const strands = [];
for (let k = 0; k < 8; k++) {
  const a = (k / 8) * Math.PI * 2 + Math.PI / 8;
  strands.push({ x: 60 + 13.5 * Math.sin(a), back: Math.cos(a) < 0 });
}
strands.sort((p, q) => (q.back ? 1 : 0) - (p.back ? 1 : 0));
const coil = (x) => {
  let d = 'M' + x.toFixed(2) + ' 130';
  for (let y = 131.4, s = 1; y <= 172; y += 1.4, s = -s) d += 'L' + (x + s * 0.85).toFixed(2) + ' ' + y.toFixed(1);
  return d;
};
const el = (name, attrs) => { const e = document.createElementNS(NS, name); for (const k in attrs) e.setAttribute(k, attrs[k]); return e; };
for (const s of strands) {
  cage.append(el('path', { class: 'fxw-filament__support', d: 'M60 125L' + s.x.toFixed(2) + ' 130M60 149L' + s.x.toFixed(2) + ' 172' }));
}
for (const layer of ['wire', 'halo', 'hot', 'core']) {
  for (const s of strands) {
    const p = el('path', { class: 'fxw-filament__' + layer, d: coil(s.x) });
    if (s.back) p.setAttribute('data-back', '');
    cage.append(p);
  }
}

let level = 0.72, on = true, T = T_R * Math.pow(level, 0.42), raf = 0, last = 0;

// Blackbody colour, after Tanner Helland's fit to Mitchell Charity's table (1000–40000 K).
function blackbody(t) {
  const u = Math.min(4000, Math.max(1000, t)) / 100;
  const r = 255;
  const g = Math.min(255, Math.max(0, 99.4708025861 * Math.log(u) - 161.1195681661));
  const b = u <= 19 ? 0 : Math.min(255, Math.max(0, 138.5177312231 * Math.log(u - 10) - 305.0447927307));
  return [r, Math.round(g), Math.round(b)];
}
const target = () => (on && level > 0.004 ? T_R * Math.pow(level, 0.42) : T_AMB);
const fmt = (n) => Math.round(n).toLocaleString('en-US');
function life(h) {
  // the V^−12 law only holds near rated voltage; past a million hours other failures win
  if (h >= 1e6) return '1M+';
  if (h >= 1e4) return Math.round(h / 1e3) + 'k';
  return fmt(h);
}

let shown = {};
function render() {
  // Below the Draper point (~798 K) nothing is visible; light output then rises as T^8.1.
  const rel = Math.pow(T / T_R, 8.1);
  const draper = Math.min(1, Math.max(0, (T - 780) / 260));
  const b = Math.min(1, Math.pow(rel, 0.42) * draper);
  const c = blackbody(T);
  root.style.setProperty('--fxw-filament-c', 'rgb(' + c.join(' ') + ')');
  root.style.setProperty('--fxw-filament-b', b.toFixed(3));

  const v = on ? level : 0;
  // P = V²/R with R ∝ T^1.2: a cold filament draws a real ten-fold inrush for a moment.
  const watts = v > 0 ? P_R * v * v * Math.pow(T_R / T, 1.2) : 0;
  const lumens = LM_R * rel * draper;
  const vals = {
    k: T < 400 ? '—' : fmt(T),
    w: watts.toFixed(1),
    lm: lumens < 9.95 ? lumens.toFixed(1) : fmt(lumens),
    life: v > 0.004 ? life(LIFE_R * Math.pow(v, -12)) : '—'
  };
  for (const k in vals) if (shown[k] !== vals[k]) { shown[k] = vals[k]; out[k].textContent = vals[k]; }
}

function frame(now) {
  if (!root.isConnected) return;
  raf = 0;
  const dt = Math.min(0.05, Math.max(0.001, (now - last) / 1000)); last = now;
  const tt = target();
  // Heating is fast (watts in), cooling slower (radiation out) — the afterglow on switch-off.
  const tau = tt > T ? 0.07 : 0.3;
  T += (tt - T) * (1 - Math.exp(-dt / tau));
  render();
  if (Math.abs(tt - T) > 0.5) raf = requestAnimationFrame(frame);
  else { T = tt; render(); }
}
function kick() { if (!raf) { last = performance.now(); raf = requestAnimationFrame(frame); } }

function sync() {
  const pct = Math.round(level * 100);
  knob.style.setProperty('--fxw-filament-lvl', level.toFixed(4));
  knob.setAttribute('aria-valuenow', pct);
  knob.setAttribute('aria-valuetext', pct + ' percent, ' + (on ? 'on' : 'off'));
  out.level.textContent = pct;
  out.state.textContent = on ? 'On' : 'Off · push';
  root.toggleAttribute('data-on', on);
  kick();
}
function setLevel(v) { level = Math.min(1, Math.max(0, v)); sync(); }
function toggle() { on = !on; sync(); }

// Turn to dim: follow the pointer's angle around the knob centre, unwrapped.
let drag = null;
const angleOf = (e) => {
  const r = knob.getBoundingClientRect();
  return Math.atan2(e.clientX - (r.left + r.width / 2), -(e.clientY - (r.top + r.height / 2))) * 180 / Math.PI;
};
knob.addEventListener('pointerdown', (e) => {
  if (e.button !== 0) return;
  knob.setPointerCapture(e.pointerId);
  drag = { a: angleOf(e), x: e.clientX, y: e.clientY, moved: false };
});
knob.addEventListener('pointermove', (e) => {
  if (!drag) return;
  if (!drag.moved && Math.hypot(e.clientX - drag.x, e.clientY - drag.y) < 4) return;
  if (!drag.moved) { drag.moved = true; knob.setAttribute('data-drag', ''); }
  const a = angleOf(e);
  let d = a - drag.a;
  if (d > 180) d -= 360; if (d < -180) d += 360;
  drag.a = a;
  setLevel(level + d / 270);
});
const release = () => {
  if (!drag) return;
  // push to switch: a press that never turned is a click on the switch
  if (!drag.moved) toggle();
  drag = null;
  knob.removeAttribute('data-drag');
};
knob.addEventListener('pointerup', release);
knob.addEventListener('pointercancel', () => { drag = null; knob.removeAttribute('data-drag'); });
knob.addEventListener('keydown', (e) => {
  const big = e.shiftKey ? 0.1 : 0.01;
  const map = { ArrowUp: big, ArrowRight: big, ArrowDown: -big, ArrowLeft: -big, PageUp: 0.1, PageDown: -0.1 };
  if (e.key in map) { e.preventDefault(); setLevel(level + map[e.key]); }
  else if (e.key === 'Home') { e.preventDefault(); setLevel(0); }
  else if (e.key === 'End') { e.preventDefault(); setLevel(1); }
  else if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); toggle(); }
});
knob.addEventListener('wheel', (e) => {
  if (document.activeElement !== knob) return;
  e.preventDefault();
  setLevel(level - Math.sign(e.deltaY) * 0.02);
}, { passive: false });

// Keep the light pool centred on the bulb as the card resizes.
const ro = new ResizeObserver(() => {
  if (!root.isConnected) { ro.disconnect(); return; }
  const rr = root.getBoundingClientRect(), sr = svg.getBoundingClientRect();
  if (!sr.width) return;
  const s = Math.min(sr.width / 120, sr.height / 240);
  root.style.setProperty('--fxw-filament-px', (sr.left - rr.left + (sr.width - 120 * s) / 2 + 60 * s).toFixed(1) + 'px');
  root.style.setProperty('--fxw-filament-py', (sr.top - rr.top + 163 * s).toFixed(1) + 'px');
});
ro.observe(root);
sync();
render();

css:
.fxw-laser {
  /* Re-theme with these four: the breadboard, the ink, the beam, and the anodised parts. */
  --fxw-laser-plate: oklch(0.935 0.006 240);
  --fxw-laser-ink: oklch(0.26 0.012 255);
  --fxw-laser-beam: oklch(0.6 0.245 27);
  --fxw-laser-metal: oklch(0.36 0.02 255);

  --fxw-laser-muted: color-mix(in oklch, var(--fxw-laser-ink) 56%, var(--fxw-laser-plate));
  --fxw-laser-rule: color-mix(in oklch, var(--fxw-laser-ink) 13%, transparent);
  --fxw-laser-hole: color-mix(in oklch, var(--fxw-laser-ink) 20%, var(--fxw-laser-plate));
  --fxw-laser-silver: color-mix(in oklch, var(--fxw-laser-plate) 40%, white);
  --fxw-laser-hot: color-mix(in oklch, var(--fxw-laser-beam) 35%, white);
  --fxw-laser-out: cubic-bezier(.16, 1, .3, 1);
  --fxw-laser-spring: linear(0, 0.24 7%, 0.72 18%, 1.02 29%, 1.08 37%, 1.05 47%, 1 60%, 0.995 76%, 1);
  --fxw-laser-mono: ui-monospace, Menlo, Consolas, monospace;

  container-type: inline-size;
  position: relative;
  isolation: isolate;
  overflow: clip;
  box-sizing: border-box;
  inline-size: 100%;
  display: grid;
  grid-template-areas: "board" "status";
  gap: 10px;
  padding: clamp(10px, 3.4%, 14px);
  border-radius: 16px;
  color: var(--fxw-laser-ink);
  background: color-mix(in oklch, var(--fxw-laser-plate) 55%, white);
  box-shadow: inset 0 0 0 1px var(--fxw-laser-rule);
  font: 500 12px/1.3 system-ui, -apple-system, "Segoe UI", sans-serif;
  -webkit-font-smoothing: antialiased;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(p) { margin: 0; }

  & .fxw-laser__board {
    grid-area: board;
    border-radius: 10px;
    background:
      linear-gradient(160deg, color-mix(in oklch, var(--fxw-laser-plate) 80%, white), var(--fxw-laser-plate) 45%, color-mix(in oklch, var(--fxw-laser-plate) 92%, var(--fxw-laser-ink)));
    box-shadow: inset 0 0 0 1px var(--fxw-laser-rule), 0 1px 0 white, 0 8px 18px -12px color-mix(in oklch, var(--fxw-laser-ink) 60%, transparent);
    overflow: clip;
    & svg { display: block; inline-size: 100%; block-size: auto; aspect-ratio: 325 / 225; overflow: visible; }
  }

  & .fxw-laser__holes circle { fill: var(--fxw-laser-hole); }
  & .fxw-laser__labels text, & .fxw-laser__tag {
    font: 600 8.5px var(--fxw-laser-mono);
    letter-spacing: .08em;
    fill: var(--fxw-laser-muted);
  }
  & .fxw-laser__tag { text-anchor: middle; pointer-events: none; }

  & .fxw-laser__body { fill: var(--fxw-laser-metal); }
  & .fxw-laser__nose { fill: color-mix(in oklch, var(--fxw-laser-metal) 70%, white); }
  & .fxw-laser__fins { stroke: color-mix(in oklch, var(--fxw-laser-metal) 60%, white); stroke-width: 1; opacity: .5; }
  & .fxw-laser__led { fill: oklch(0.8 0.2 145); animation: fxw-laser-blink 1.6s steps(1, end) infinite; }

  & .fxw-laser__post { fill: var(--fxw-laser-metal); }
  & .fxw-laser__face { fill: color-mix(in oklch, var(--fxw-laser-metal) 85%, black); stroke: color-mix(in oklch, var(--fxw-laser-metal) 55%, white); stroke-width: 1.4; }
  & .fxw-laser__active { fill: oklch(0.32 0.04 255); transition: fill .4s var(--fxw-laser-out); }
  & .fxw-laser__seek {
    fill: none; stroke: var(--fxw-laser-beam); stroke-width: 1;
    transform-box: fill-box; transform-origin: center;
    animation: fxw-laser-seek 2.4s cubic-bezier(.2, .7, .3, 1) infinite;
  }
  &[data-hit] .fxw-laser__seek { animation: none; opacity: 0; }
  &[data-hit] .fxw-laser__active { fill: var(--fxw-laser-hot); }

  /* The beam: a soft halo of scattered light, the core, and a slow photon dash. */
  & .fxw-laser__beam polyline { fill: none; stroke-linecap: round; stroke-linejoin: round; }
  & .fxw-laser__glow { stroke: var(--fxw-laser-beam); stroke-width: 7; opacity: .34; filter: blur(3px); }
  & .fxw-laser__core { stroke: var(--fxw-laser-beam); stroke-width: 1.5; }
  & .fxw-laser__flow {
    stroke: var(--fxw-laser-hot); stroke-width: .8;
    stroke-dasharray: 2 16;
    opacity: .75;
    animation: fxw-laser-flow 1.1s linear infinite;
  }
  & .fxw-laser__spots circle { fill: var(--fxw-laser-hot); }
  & .fxw-laser__spots .fxw-laser__halo { fill: var(--fxw-laser-beam); opacity: .3; filter: blur(2.5px); }

  /* Mirrors on kinematic mounts. Focus shows a dial ring; dragging turns the mount. */
  & .fxw-laser__mirror {
    cursor: grab;
    outline: none;
    touch-action: none;
    &[data-drag] { cursor: grabbing; }
  }
  & .fxw-laser__hit { fill: transparent; }
  & .fxw-laser__base { fill: color-mix(in oklch, var(--fxw-laser-plate) 70%, white); stroke: color-mix(in oklch, var(--fxw-laser-ink) 22%, transparent); stroke-width: .8; }
  & .fxw-laser__mount { fill: var(--fxw-laser-metal); }
  & .fxw-laser__screw { fill: color-mix(in oklch, var(--fxw-laser-metal) 60%, white); }
  & .fxw-laser__glass { fill: color-mix(in oklch, var(--fxw-laser-silver) 70%, var(--fxw-laser-metal)); }
  & .fxw-laser__coat { stroke: white; stroke-width: 1.2; stroke-linecap: round; }
  & .fxw-laser__dial {
    fill: none;
    stroke: var(--fxw-laser-ink);
    stroke-width: 1;
    stroke-dasharray: 1.5 3;
    opacity: 0;
    transition: opacity .25s var(--fxw-laser-out);
  }
  & .fxw-laser__mirror:hover .fxw-laser__dial { opacity: .35; }
  & .fxw-laser__mirror:focus-visible .fxw-laser__dial { opacity: 1; stroke-dasharray: none; stroke-width: 1.5; }

  /* ---------- status ---------- */
  & .fxw-laser__status {
    grid-area: status;
    display: grid;
    grid-template-columns: auto 1fr auto;
    grid-template-areas: "meter loss reset";
    align-items: center;
    gap: 6px 14px;
  }
  & .fxw-laser__meter { grid-area: meter; display: grid; gap: 1px; }
  & .fxw-laser__label {
    font: 600 9.5px/1.2 var(--fxw-laser-mono);
    letter-spacing: .1em;
    text-transform: uppercase;
    color: var(--fxw-laser-muted);
    & span { margin-inline-start: 4px; color: var(--fxw-laser-ink); }
  }
  &[data-hit] .fxw-laser__label span { color: color-mix(in oklch, var(--fxw-laser-beam) 85%, black); }
  & .fxw-laser__power {
    display: flex;
    align-items: baseline;
    gap: 4px;
    font-variant-numeric: tabular-nums;
    & b { font-size: clamp(20px, 6.6cqi, 26px); font-weight: 700; letter-spacing: -.03em; line-height: 1; }
    & span { font-weight: 600; color: var(--fxw-laser-muted); }
    & em { font: 500 10.5px/1 var(--fxw-laser-mono); font-style: normal; color: var(--fxw-laser-muted); margin-inline-start: 4px; }
  }
  & .fxw-laser__loss {
    grid-area: loss;
    font: 500 10.5px/1.35 var(--fxw-laser-mono);
    color: var(--fxw-laser-muted);
    font-variant-numeric: tabular-nums;
    text-wrap: pretty;
  }
  & .fxw-laser__reset {
    grid-area: reset;
    padding: 6px 12px;
    border: 1px solid var(--fxw-laser-rule);
    border-radius: 999px;
    background: white;
    color: var(--fxw-laser-ink);
    font: 600 11px/1 system-ui, sans-serif;
    cursor: pointer;
    transition: border-color .2s var(--fxw-laser-out), scale .25s var(--fxw-laser-spring);
    &:hover { border-color: color-mix(in oklch, var(--fxw-laser-ink) 35%, transparent); }
    &:active { scale: .96; }
    &:focus-visible { outline: 2px solid var(--fxw-laser-beam); outline-offset: 2px; }
  }
  & .fxw-laser__sr {
    position: absolute; inline-size: 1px; block-size: 1px; overflow: hidden;
    clip-path: inset(50%); white-space: nowrap;
  }

  @container (max-width: 340px) {
    & .fxw-laser__status { grid-template-columns: 1fr auto; grid-template-areas: "meter reset" "loss loss"; }
  }
}

@keyframes fxw-laser-blink { 0% { opacity: 1; } 50% { opacity: .25; } }
@keyframes fxw-laser-flow { to { stroke-dashoffset: -18; } }
@keyframes fxw-laser-seek {
  from { scale: 1; opacity: .7; }
  to { scale: 2.1; opacity: 0; }
}

@media (prefers-reduced-motion: reduce) {
  .fxw-laser .fxw-laser__flow { animation: none; opacity: .5; }
