const NS = 'http://www.w3.org/2000/svg';
const calmQ = matchMedia('(prefers-reduced-motion: reduce)');
const svg = root.querySelector('svg');
const holes = root.querySelector('.fxw-laser__holes');
const lines = [...root.querySelectorAll('.fxw-laser__beam polyline')];
const spots = root.querySelector('.fxw-laser__spots');
const outMw = root.querySelector('[data-mw]');
const outState = root.querySelector('[data-state]');
const outLoss = root.querySelector('[data-loss]');
const sr = root.querySelector('.fxw-laser__sr');
const resetBtn = root.querySelector('.fxw-laser__reset');
const el = (name, attrs) => { const e = document.createElementNS(NS, name); for (const k in attrs) e.setAttribute(k, attrs[k]); return e; };

// M6 breadboard: 25 mm pitch, 13 × 9 holes.
const BW = 325, BH = 225;
for (let i = 0; i < 13; i++) for (let j = 0; j < 9; j++) holes.append(el('circle', { cx: 12.5 + i * 25, cy: 12.5 + j * 25, r: 2.3 }));

const SOURCE = { x: 78, y: 70, mw: 5 };
const DET = { x: 300, y: 46, r: 10, active: 5.5 };
const LOSS = 0.96;           // each silvered bounce keeps 96 %
const STEP = 2.5;            // the mount's fine-pitch adjuster, in degrees
const HALF = 12;             // half the mirror's clear aperture

const mirrors = [...root.querySelectorAll('.fxw-laser__mirror')].map((g, i) => {
  const rot = el('g', { class: 'fxw-laser__rot' });
  rot.append(
    el('circle', { class: 'fxw-laser__hit', r: 22 }),
    el('circle', { class: 'fxw-laser__dial', r: 19 }),
    el('circle', { class: 'fxw-laser__base', r: 11 }),
    el('rect', { class: 'fxw-laser__mount', x: -9, y: -13, width: 6, height: 26, rx: 1.5 }),
    el('circle', { class: 'fxw-laser__screw', cx: -11.5, cy: -8, r: 2 }),
    el('circle', { class: 'fxw-laser__screw', cx: -11.5, cy: 8, r: 2 }),
    el('rect', { class: 'fxw-laser__glass', x: -3, y: -12, width: 4, height: 24, rx: 0.8 }),
    el('path', { class: 'fxw-laser__coat', d: 'M1 -11.4V11.4' })
  );
  g.prepend(rot);
  const a = +g.dataset.a;
  return { g, rot, x: +g.dataset.x, y: +g.dataset.y, a0: a, a, ad: a, name: 'M' + (i + 1) };
});

const norm = (a) => ((a % 360) + 360) % 360;
function place(m) {
  m.rot.setAttribute('transform', 'translate(' + m.x + ' ' + m.y + ') rotate(' + m.ad.toFixed(2) + ')');
}
function aria(m) {
  const v = norm(m.a);
  m.g.setAttribute('aria-valuenow', v);
  m.g.setAttribute('aria-valuetext', v + ' degrees');
}

// Trace one ray: nearest of mirror faces, the detector, the laser housing and the board edge.
function trace() {
  let px = SOURCE.x, py = SOURCE.y, dx = 1, dy = 0, last = -1, bounces = 0;
  const pts = [[px, py]], hits = [];
  let end = 'edge', who = '';
  for (let k = 0; k < 12; k++) {
    let best = Infinity, kind = null, idx = -1;
    mirrors.forEach((m, i) => {
      if (i === last) return;
      const a = m.ad * Math.PI / 180, nx = Math.cos(a), ny = Math.sin(a);
      const fx = m.x + nx, fy = m.y + ny;                  // the silvered front face
      const ex = -ny * HALF, ey = nx * HALF;               // half-length along the face
      const den = dx * (2 * ey) - dy * (2 * ex);
      if (Math.abs(den) < 1e-9) return;
      const ax = fx - ex - px, ay = fy - ey - py;
      const t = (ax * (2 * ey) - ay * (2 * ex)) / den;
      const s = (ax * dy - ay * dx) / den;
      if (t > 1e-6 && s >= 0 && s <= 1 && t < best) { best = t; kind = 'mirror'; idx = i; }
    });
    // detector face: a circle; inside the active radius it is a reading, outside it is the housing
    const ox = px - DET.x, oy = py - DET.y, bq = ox * dx + oy * dy, cq = ox * ox + oy * oy - DET.r * DET.r;
    const disc = bq * bq - cq;
    if (disc >= 0) {
      const t = -bq - Math.sqrt(disc);
      if (t > 1e-6 && t < best) { best = t; kind = 'detector'; }
    }
    // laser housing
    if (dx < 0) {
      const t = (72 - px) / dx, yy = py + dy * t;
      if (t > 1e-6 && t < best && yy >= 60 && yy <= 80) { best = t; kind = 'laser'; }
    }
    // board edge
    const te = Math.min(dx > 0 ? (BW - px) / dx : dx < 0 ? -px / dx : Infinity, dy > 0 ? (BH - py) / dy : dy < 0 ? -py / dy : Infinity);
    if (te < best) { best = te; kind = 'edge'; }

    px += dx * best; py += dy * best;
    pts.push([px, py]);
    if (kind === 'mirror') {
      const m = mirrors[idx], a = m.ad * Math.PI / 180, nx = Math.cos(a), ny = Math.sin(a);
      const dn = dx * nx + dy * ny;
      if (dn >= 0) { end = 'mount'; who = m.name; break; }       // struck the back of the mount
      dx -= 2 * dn * nx; dy -= 2 * dn * ny;                       // d − 2(d·n)n
      bounces++; last = idx;
      hits.push([px, py]);
      continue;
    }
    if (kind === 'detector') {
      // perpendicular distance of the ray from the detector centre decides whether it lands on the diode
      const miss = Math.abs((DET.x - pts[pts.length - 2][0]) * dy - (DET.y - pts[pts.length - 2][1]) * dx);
      end = miss <= DET.active ? 'hit' : 'housing';
    } else end = kind;
    break;
  }
  return { pts, hits, end, who, bounces, mw: end === 'hit' ? SOURCE.mw * Math.pow(LOSS, bounces) : 0 };
}

const SUP = '⁰¹²³⁴⁵⁶⁷⁸⁹';
const sup = (n) => String(n).split('').map((c) => SUP[+c]).join('');
let shownMw = 0, goalMw = 0, tween = null, lastEnd = '';

function render() {
  const r = trace();
  const pts = r.pts.map((p) => p[0].toFixed(1) + ',' + p[1].toFixed(1)).join(' ');
  lines.forEach((l) => l.setAttribute('points', pts));
  spots.replaceChildren();
  for (const [x, y] of r.hits) {
    spots.append(el('circle', { class: 'fxw-laser__halo', cx: x, cy: y, r: 5 }), el('circle', { cx: x, cy: y, r: 1.5 }));
  }
  const [ex, ey] = r.pts[r.pts.length - 1];
  spots.append(el('circle', { class: 'fxw-laser__halo', cx: ex, cy: ey, r: r.end === 'hit' ? 9 : 5 }), el('circle', { cx: ex, cy: ey, r: r.end === 'hit' ? 2.6 : 1.6 }));

  root.toggleAttribute('data-hit', r.end === 'hit');
  outState.textContent = r.end === 'hit' ? 'Aligned' : 'No signal';
  const b = r.bounces, s = b === 1 ? '' : 's';
  outLoss.textContent =
    r.end === 'hit' ? b + ' bounce' + s + ' · 5.00 × 0.96' + sup(b) + ' = ' + r.mw.toFixed(2) + ' mW'
    : r.end === 'mount' ? 'Blocked by the back of ' + r.who
    : r.end === 'housing' ? 'Clipping the detector housing'
    : r.end === 'laser' ? 'Reflected back into the laser'
    : 'Beam leaves the board after ' + b + ' bounce' + s;
  if (r.end !== lastEnd && (r.end === 'hit' || lastEnd === 'hit')) {
    sr.textContent = r.end === 'hit' ? 'Aligned. ' + r.mw.toFixed(2) + ' milliwatts at the detector.' : 'Signal lost.';
  }
  lastEnd = r.end;
  if (Math.abs(r.mw - goalMw) > 1e-6) {
    goalMw = r.mw;
    tween = { from: shownMw, t0: performance.now() };
  }
}

let raf = 0, last = 0;
function frame(now) {
  if (!root.isConnected) return;
  raf = 0;
  const dt = Math.min(0.05, Math.max(0.001, (now - last) / 1000)); last = now;
  const calm = calmQ.matches;
  let busy = false;
  for (const m of mirrors) {
    const k = calm ? 1 : 1 - Math.exp(-dt / 0.06);
    m.ad += (m.a - m.ad) * k;
    if (Math.abs(m.a - m.ad) < 0.01) m.ad = m.a; else busy = true;
    place(m);
  }
  render();
  if (tween) {
    const u = calm ? 1 : Math.min(1, (now - tween.t0) / 450);
    shownMw = tween.from + (goalMw - tween.from) * (1 - Math.pow(1 - u, 3));
    outMw.textContent = shownMw.toFixed(2);
    if (u >= 1) tween = null; else busy = true;
  }
  if (busy) raf = requestAnimationFrame(frame);
}
function kick() { if (!raf) { last = performance.now(); raf = requestAnimationFrame(frame); } }
const snap = (a) => Math.round(a / STEP) * STEP;

mirrors.forEach((m) => {
  let drag = null;
  const centre = () => { const p = new DOMPoint(m.x, m.y).matrixTransform(svg.getScreenCTM()); return p; };
  const ang = (e, c) => Math.atan2(e.clientY - c.y, e.clientX - c.x) * 180 / Math.PI;
  m.g.addEventListener('pointerdown', (e) => {
    if (e.button !== 0) return;
    m.g.setPointerCapture(e.pointerId);
    const c = centre();
    drag = { c, start: ang(e, c), a: m.a };
    m.g.setAttribute('data-drag', '');
    m.g.focus({ preventScroll: true });
    e.preventDefault();
  });
  m.g.addEventListener('pointermove', (e) => {
    if (!drag) return;
    let d = ang(e, drag.c) - drag.start;
    if (d > 180) d -= 360; if (d < -180) d += 360;
    const a = snap(drag.a + d);
    if (a !== m.a) { m.a = a; aria(m); kick(); }
  });
  const up = () => { drag = null; m.g.removeAttribute('data-drag'); };
  m.g.addEventListener('pointerup', up);
  m.g.addEventListener('pointercancel', up);
  m.g.addEventListener('keydown', (e) => {
    const big = e.shiftKey ? STEP * 6 : STEP;
    const d = { ArrowRight: big, ArrowUp: big, ArrowLeft: -big, ArrowDown: -big, PageUp: STEP * 6, PageDown: -STEP * 6 }[e.key];
    if (d !== undefined) { e.preventDefault(); m.a = snap(m.a + d); }
    else if (e.key === 'Home') { e.preventDefault(); m.a = m.a0; }
    else return;
    aria(m); kick();
  });
  m.g.addEventListener('wheel', (e) => {
    if (document.activeElement !== m.g) return;
    e.preventDefault();
    m.a = snap(m.a - Math.sign(e.deltaY) * STEP); aria(m); kick();
  }, { passive: false });
});

resetBtn.addEventListener('click', () => { mirrors.forEach((m) => { m.a = m.a0; aria(m); }); kick(); });

mirrors.forEach((m) => { place(m); aria(m); });
render();
outMw.textContent = goalMw.toFixed(2);
shownMw = goalMw; tween = null;

