.fxw-stage {
  /* Re-theme with these four: the three gels and the house. Gels should stay near the primaries to mix to white. */
  --fxw-stage-r: oklch(0.64 0.25 28);
  --fxw-stage-g: oklch(0.86 0.27 144);
  --fxw-stage-b: oklch(0.56 0.26 265);
  --fxw-stage-house: oklch(0.17 0.008 280);

  --fxw-stage-ink: oklch(0.95 0.005 280);
  --fxw-stage-muted: color-mix(in oklch, var(--fxw-stage-ink) 55%, var(--fxw-stage-house));
  --fxw-stage-rule: color-mix(in oklch, var(--fxw-stage-ink) 12%, transparent);
  --fxw-stage-out: cubic-bezier(.16, 1, .3, 1);
  --fxw-stage-mono: ui-monospace, Menlo, Consolas, monospace;

  container-type: inline-size;
  position: relative;
  isolation: isolate;
  overflow: clip;
  box-sizing: border-box;
  inline-size: 100%;
  display: grid;
  grid-template-areas: "head" "view" "desk";
  gap: 8px;
  padding: clamp(8px, 2.8%, 12px);
  border-radius: 16px;
  color: var(--fxw-stage-ink);
  background: var(--fxw-stage-house);
  box-shadow: inset 0 0 0 1px var(--fxw-stage-rule);
  font: 500 12px/1.3 system-ui, -apple-system, "Segoe UI", sans-serif;
  -webkit-font-smoothing: antialiased;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(p, ul) { margin: 0; padding: 0; }

  & .fxw-stage__view {
    grid-area: view;
    position: relative;
    aspect-ratio: 16 / 10.5;
    min-block-size: 160px;
    max-block-size: 290px;
    border-radius: 10px;
    overflow: clip;
    background: black;
  }
  & .fxw-stage__canvas { position: absolute; inset: 0; inline-size: 100%; block-size: 100%; display: block; }

  & .fxw-stage__head {
    grid-area: head;
    display: flex;
    padding-inline: 4px;
    justify-content: space-between;
    align-items: center;
    gap: 8px;
  }
  & .fxw-stage__title {
    font: 600 9.5px/1.2 var(--fxw-stage-mono);
    letter-spacing: .12em;
    text-transform: uppercase;
    color: var(--fxw-stage-muted);
  }
  & .fxw-stage__shadows {
    display: flex;
    align-items: center;
    gap: 7px;
    padding: 4px 6px;
    border-radius: 8px;
    background: color-mix(in oklch, var(--fxw-stage-house) 70%, transparent);
    box-shadow: 0 0 0 1px var(--fxw-stage-rule);
    & ul { list-style: none; display: flex; gap: 6px; }
    & li { display: flex; align-items: center; gap: 3px; font: 600 9px/1 var(--fxw-stage-mono); color: var(--fxw-stage-muted); }
    & i {
      inline-size: 11px; block-size: 11px; border-radius: 3px;
      background: var(--fxw-stage-sh, #000);
      box-shadow: inset 0 0 0 1px color-mix(in oklch, white 22%, transparent);
      transition: background-color .3s var(--fxw-stage-out);
    }
  }

  & .fxw-stage__handle {
    --fxw-stage-c: var(--fxw-stage-r);
    position: absolute;
    inset-inline-start: calc(var(--fxw-stage-x, .5) * 100%);
    inset-block-start: calc(var(--fxw-stage-y, .8) * 100%);
    inline-size: 32px;
    block-size: 32px;
    margin: -16px 0 0 -16px;
    padding: 0;
    border: 0;
    border-radius: 50%;
    background: none;
    cursor: grab;
    touch-action: none;
    &::before {
      content: "";
      position: absolute;
      inset: 9px;
      border-radius: 50%;
      border: 1.5px solid color-mix(in oklch, var(--fxw-stage-c) 75%, white);
      background: color-mix(in oklch, var(--fxw-stage-c) 18%, transparent);
      box-shadow: 0 0 10px color-mix(in oklch, var(--fxw-stage-c) 60%, transparent);
      transition: scale .3s var(--fxw-stage-out), border-width .2s var(--fxw-stage-out);
    }
    &:hover::before { scale: 1.2; }
    &:focus-visible { outline: none; }
    &:focus-visible::before { border-width: 2.5px; scale: 1.25; border-color: white; }
    &[data-drag] { cursor: grabbing; }
  }
  & .fxw-stage__handle[data-ch="1"] { --fxw-stage-c: var(--fxw-stage-g); }
  & .fxw-stage__handle[data-ch="2"] { --fxw-stage-c: var(--fxw-stage-b); }
  & .fxw-stage__actor {
    --fxw-stage-c: var(--fxw-stage-ink);
    &::before { inset: 11px; border-style: dashed; background: none; box-shadow: none; opacity: .55; }
  }

  & .fxw-stage__desk {
    grid-area: desk;
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 10px;
    padding: 0 4px 2px;
    & label { display: grid; gap: 5px; min-inline-size: 0; }
    & span {
      font: 600 10px/1 var(--fxw-stage-mono);
      letter-spacing: .06em;
      color: var(--fxw-stage-muted);
      font-variant-numeric: tabular-nums;
      & b { color: var(--fxw-stage-ink); font-weight: 700; margin-inline-start: 2px; }
    }
    & input { inline-size: 100%; margin: 0; cursor: pointer; accent-color: var(--fxw-stage-r); }
    & input:focus-visible { outline: 2px solid var(--fxw-stage-ink); outline-offset: 3px; border-radius: 4px; }
    & [data-ch="1"] input { accent-color: var(--fxw-stage-g); }
    & [data-ch="2"] input { accent-color: var(--fxw-stage-b); }
    & label:has(input:focus-visible) span { color: var(--fxw-stage-ink); }
  }

  & .fxw-stage__cap { font: 600 8.5px/1 var(--fxw-stage-mono); letter-spacing: .1em; text-transform: uppercase; color: var(--fxw-stage-muted); }

  @container (max-width: 330px) {
    & .fxw-stage__cap { display: none; }
  }
}

@media (prefers-reduced-motion: reduce) {
  .fxw-stage .fxw-stage__handle::before,
  .fxw-stage .fxw-stage__shadows i { transition: none; }
}

