const calmQ = matchMedia('(prefers-reduced-motion: reduce)');
const view = root.querySelector('.fxw-stage__view');
const cv = root.querySelector('.fxw-stage__canvas');
const ctx = cv.getContext('2d');
const handles = [...root.querySelectorAll('.fxw-stage__handle')];
const faders = [...root.querySelectorAll('.fxw-stage__desk input')];
const faderOut = [...root.querySelectorAll('.fxw-stage__desk b')];
const chips = [...root.querySelectorAll('.fxw-stage__shadows li')];

const mk = (o) => { const c = document.createElement('canvas'); return [c, c.getContext('2d', o)]; };
const [lb, lctx] = mk();          // one fixture's light, before it is summed
const [acc, actx] = mk();         // the summed light falling on surfaces
const [hz, hctx] = mk();          // beams in the haze
const [alb, alctx] = mk();        // surface albedo: cyc, floor, planks
const [probe, pctx] = mk({ willReadFrequently: true });
probe.width = probe.height = 1;
function rgb(name) {
  pctx.clearRect(0, 0, 1, 1);
  pctx.fillStyle = '#888';
  pctx.fillStyle = getComputedStyle(root).getPropertyValue(name).trim() || '#888';
  pctx.fillRect(0, 0, 1, 1);
  const d = pctx.getImageData(0, 0, 1, 1).data;
  return [d[0], d[1], d[2]];
}
const css = (c, a = 1) => 'rgb(' + c.map((v) => Math.round(Math.min(255, Math.max(0, v)))).join(' ') + ' / ' + a + ')';

const NAMES = ['Red', 'Green', 'Blue'];
const FIX = [0.2, 0.5, 0.8];                                  // fixtures along the front truss
const pools = [{ x: 0.4, y: 0.82 }, { x: 0.5, y: 0.75 }, { x: 0.6, y: 0.82 }];
const actor = { x: 0.5, y: 0.8, tx: 0.5 };
const level = [1, 1, 1];
let gels = [], W = 0, H = 0, dpr = 1, S = 0.5, visible = false, raf = 0, last = 0, t = 0, userAt = -1e9;
const WALL_ALB = 0.82, FLOOR_ALB = 0.36, AMBIENT = 12;

const floorTop = () => H * 0.56;
// Same falloff the gradients draw, so readouts agree with the picture.
const fall = (d) => (d >= 1 ? 0 : d < 0.55 ? 1 - 0.2 * d / 0.55 : 0.8 * (1 - (d - 0.55) / 0.45));
const wallC = (p) => ({ x: p.x * W, y: floorTop() - H * 0.2, r: W * 0.38 });
const floorC = (p) => ({ x: p.x * W, y: p.y * H, rx: W * 0.2, ry: W * 0.2 * 0.4 });

function figure(g, x, y, h, sx = 1) {
  // a dancer mid-step, drawn feet-first in units of height
  const P = (u, v) => [x + u * h * sx, y - v * h];
  g.beginPath();
  g.moveTo(...P(-0.11, 0)); g.lineTo(...P(-0.06, 0));
  g.lineTo(...P(-0.01, 0.4)); g.lineTo(...P(0.05, 0.02)); g.lineTo(...P(0.12, 0.02));
  g.lineTo(...P(0.05, 0.47)); g.lineTo(...P(0.07, 0.72));
  g.lineTo(...P(0.24, 0.92)); g.lineTo(...P(0.21, 0.95)); g.lineTo(...P(0.05, 0.8));
  g.lineTo(...P(0.03, 0.83)); g.lineTo(...P(-0.03, 0.83));
  g.lineTo(...P(-0.16, 0.66)); g.lineTo(...P(-0.27, 0.7)); g.lineTo(...P(-0.28, 0.67)); g.lineTo(...P(-0.15, 0.6));
  g.lineTo(...P(-0.07, 0.7)); g.lineTo(...P(-0.07, 0.47));
  g.closePath();
  const [hx, hy] = P(0, 0.9);
  g.moveTo(hx + 0.065 * h, hy);
  g.arc(hx, hy, 0.065 * h, 0, Math.PI * 2);
}

function shadowShift(i) { return (actor.x - FIX[i]) * W * 0.42; }

function build() {
  gels = [rgb('--fxw-stage-r'), rgb('--fxw-stage-g'), rgb('--fxw-stage-b')];
  const lw = Math.ceil(W * S), lh = Math.ceil(H * S);
  for (const c of [lb, acc, hz]) { c.width = lw; c.height = lh; }
  alb.width = Math.round(W * dpr); alb.height = Math.round(H * dpr);
  const a = alctx, ft = floorTop();
  a.setTransform(dpr, 0, 0, dpr, 0, 0);
  let g = a.createLinearGradient(0, 0, 0, ft);
  g.addColorStop(0, css([200, 200, 205])); g.addColorStop(0.85, css([214, 214, 218])); g.addColorStop(1, css([170, 170, 176]));
  a.fillStyle = g; a.fillRect(0, 0, W, ft);
  g = a.createLinearGradient(0, ft, 0, H);
  g.addColorStop(0, css([70, 64, 60])); g.addColorStop(1, css([100, 90, 82]));
  a.fillStyle = g; a.fillRect(0, ft, W, H - ft);
  // deck boards converge on a vanishing point above the cyc
  a.strokeStyle = css([40, 36, 34]); a.lineWidth = 1;
  const vx = W / 2, vy = ft - H * 0.9;
  for (let k = -12; k <= 12; k++) {
    const bx = W / 2 + k * W * 0.09;
    const u = (ft - vy) / (H - vy);
    a.beginPath(); a.moveTo(vx + (bx - vx) * u, ft); a.lineTo(bx, H); a.stroke();
  }
  a.fillStyle = css([150, 150, 156]); a.fillRect(0, ft - 1, W, 1.5);
}

function draw() {
  if (!W) return;
  const ft = floorTop(), h = H * 0.36, ax = actor.x * W, ay = actor.y * H;
  // ambient fills every device pixel, so the albedo multiply never meets a transparent edge
  actx.setTransform(1, 0, 0, 1, 0, 0);
  actx.globalCompositeOperation = 'source-over';
  actx.fillStyle = css([AMBIENT, AMBIENT, AMBIENT + 3]); actx.fillRect(0, 0, acc.width, acc.height);
  hctx.setTransform(S, 0, 0, S, 0, 0);
  hctx.globalCompositeOperation = 'source-over';
  hctx.clearRect(0, 0, W, H);

  for (let i = 0; i < 3; i++) {
    const c = gels[i].map((v) => v * level[i]);
    if (level[i] <= 0) continue;
    lctx.setTransform(S, 0, 0, S, 0, 0);
    lctx.globalCompositeOperation = 'source-over'; lctx.filter = 'none';
    lctx.clearRect(0, 0, W, H);
    // wash on the cyc
    const w = wallC(pools[i]);
    let g = lctx.createRadialGradient(w.x, w.y, 0, w.x, w.y, w.r);
    g.addColorStop(0, css(c)); g.addColorStop(0.55, css(c, 0.8)); g.addColorStop(1, css(c, 0));
    lctx.fillStyle = g; lctx.fillRect(0, 0, W, ft);
    // pool on the deck, an ellipse in perspective
    const f = floorC(pools[i]);
    lctx.save();
    lctx.beginPath(); lctx.rect(0, ft, W, H - ft); lctx.clip();
    lctx.translate(f.x, f.y); lctx.scale(1, f.ry / f.rx);
    g = lctx.createRadialGradient(0, 0, 0, 0, 0, f.rx);
    g.addColorStop(0, css(c)); g.addColorStop(0.55, css(c, 0.8)); g.addColorStop(1, css(c, 0));
    lctx.fillStyle = g; lctx.fillRect(-f.rx, -f.rx, f.rx * 2, f.rx * 2);
    lctx.restore();
    // this fixture's shadow: deck strip running upstage, then the figure climbing the cyc
    const dx = shadowShift(i), s = 1.2;
    lctx.globalCompositeOperation = 'destination-out';
    lctx.filter = 'blur(' + (1.6 * S * 2).toFixed(1) + 'px)';
    lctx.fillStyle = '#000';
    lctx.beginPath();
    lctx.moveTo(ax - h * 0.09, ay); lctx.lineTo(ax + h * 0.1, ay);
    lctx.lineTo(ax + dx + h * 0.12, ft + 1); lctx.lineTo(ax + dx - h * 0.12, ft + 1);
    lctx.closePath(); lctx.fill();
    figure(lctx, ax + dx, ft + 2, h * s);
    lctx.fill();
    lctx.filter = 'none';
    actx.setTransform(1, 0, 0, 1, 0, 0);
    actx.globalCompositeOperation = 'lighter';
    actx.drawImage(lb, 0, 0);
    actx.setTransform(S, 0, 0, S, 0, 0);

    // the beam itself, visible in haze from the truss down to the pool
    const fx = FIX[i] * W, fy = -H * 0.02;
    g = hctx.createLinearGradient(0, fy, 0, f.y);
    g.addColorStop(0, css(c, 0.1)); g.addColorStop(1, css(c, 0.025));
    hctx.globalCompositeOperation = 'lighter';
    hctx.fillStyle = g;
    hctx.beginPath(); hctx.moveTo(fx - 4, fy); hctx.lineTo(fx + 4, fy);
    hctx.lineTo(f.x + f.rx * 0.8, f.y); hctx.lineTo(f.x - f.rx * 0.8, f.y); hctx.closePath(); hctx.fill();
  }

  // lit surfaces = albedo × summed light
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.globalCompositeOperation = 'copy';
  ctx.imageSmoothingEnabled = true;
  ctx.drawImage(acc, 0, 0, cv.width, cv.height);
  ctx.globalCompositeOperation = 'multiply';
  ctx.drawImage(alb, 0, 0);
  ctx.globalCompositeOperation = 'lighter';
  ctx.drawImage(hz, 0, 0, cv.width, cv.height);

  // the performer, front-lit by whatever pools reach their feet
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  const lit = [0, 0, 0];
  for (let i = 0; i < 3; i++) {
    const f = floorC(pools[i]);
    const d = Math.hypot((ax - f.x) / f.rx, (ay - f.y) / f.ry);
    const k = fall(d) * level[i] * 0.42;
    for (let ch = 0; ch < 3; ch++) lit[ch] += gels[i][ch] * k;
  }
  ctx.globalCompositeOperation = 'source-over';
  const body = ctx.createLinearGradient(0, ay - h, 0, ay);
  body.addColorStop(0, css(lit.map((v) => v + 14))); body.addColorStop(1, css(lit.map((v) => v * 0.55 + 8)));
  ctx.fillStyle = body;
  figure(ctx, ax, ay, h);
  ctx.fill();

  // fixtures on the truss
  ctx.fillStyle = css([28, 28, 32]);
  ctx.fillRect(0, 0, W, H * 0.035);
  for (let i = 0; i < 3; i++) {
    const fx = FIX[i] * W;
    ctx.fillStyle = css([44, 44, 50]);
    ctx.beginPath(); ctx.roundRect(fx - 9, -2, 18, H * 0.06, 3); ctx.fill();
    const g = ctx.createRadialGradient(fx, H * 0.055, 0, fx, H * 0.055, 9);
    g.addColorStop(0, css(gels[i].map((v) => v * 0.4 + 150 * level[i]), level[i]));
    g.addColorStop(0.3, css(gels[i], 0.6 * level[i])); g.addColorStop(1, css(gels[i], 0));
    ctx.globalCompositeOperation = 'lighter';
    ctx.fillStyle = g; ctx.fillRect(fx - 10, H * 0.055 - 10, 20, 20);
    ctx.globalCompositeOperation = 'source-over';
  }
}

function legend() {
  const ft = floorTop(), h = H * 0.36;
  chips.forEach((li, i) => {
    // sample the middle of this fixture's shadow on the cyc and sum the other two washes there
    const px = actor.x * W + shadowShift(i), py = ft - h * 1.2 * 0.5;
    const c = [AMBIENT, AMBIENT, AMBIENT];
    for (let j = 0; j < 3; j++) {
      if (j === i) continue;
      const w = wallC(pools[j]);
      const k = fall(Math.hypot(px - w.x, py - w.y) / w.r) * level[j];
      for (let ch = 0; ch < 3; ch++) c[ch] += gels[j][ch] * k;
    }
    const out = c.map((v) => Math.min(255, v * WALL_ALB));
    li.querySelector('i').style.setProperty('--fxw-stage-sh', css(out));
    const on = out.map((v) => v > 90);
    const name = ['dark', 'red', 'green', 'yellow', 'blue', 'magenta', 'cyan', 'white'][(on[0] ? 1 : 0) + (on[1] ? 2 : 0) + (on[2] ? 4 : 0)];
    li.setAttribute('aria-label', NAMES[i] + ' fixture shadow: ' + name);
  });
}

function placeHandles() {
  pools.forEach((p, i) => { handles[i].style.setProperty('--fxw-stage-x', p.x.toFixed(4)); handles[i].style.setProperty('--fxw-stage-y', p.y.toFixed(4)); });
  handles[3].style.setProperty('--fxw-stage-x', actor.x.toFixed(4));
  handles[3].style.setProperty('--fxw-stage-y', (actor.y - 0.2).toFixed(4));
}

let legendAt = 0;
function frame(now) {
  if (!root.isConnected) { io.disconnect(); ro.disconnect(); return; }
  raf = 0;
  if (!visible) return;
  if (document.hidden) { raf = requestAnimationFrame(frame); return; }
  const dt = Math.min(0.05, Math.max(0.001, (now - last) / 1000)); last = now;
  const calm = calmQ.matches;
  const idle = now - userAt > 4000;
  if (idle && !calm) { t += dt; actor.tx = 0.5 + 0.13 * Math.sin(t * 0.42); }
  const k = calm ? 1 : 1 - Math.exp(-dt / (idle ? 0.4 : 0.06));
  actor.x += (actor.tx - actor.x) * k;
  placeHandles();
  draw();
  if (now - legendAt > 120) { legendAt = now; legend(); }
  if (!calm || Math.abs(actor.tx - actor.x) > 0.0005) raf = requestAnimationFrame(frame);
}
function kick() { if (!raf && visible) { last = performance.now(); raf = requestAnimationFrame(frame); } }
function touched() { userAt = performance.now(); if (calmQ.matches) { placeHandles(); draw(); legend(); } kick(); }

handles.forEach((hd, i) => {
  let drag = null;
  const move = (e) => {
    const r = view.getBoundingClientRect();
    const x = Math.min(0.95, Math.max(0.05, (e.clientX - r.left) / r.width));
    const y = Math.min(0.94, Math.max(0.64, (e.clientY - r.top) / r.height));
    if (i < 3) { pools[i].x = x; pools[i].y = y; } else { actor.tx = Math.min(0.85, Math.max(0.15, x)); }
    touched();
  };
  hd.addEventListener('pointerdown', (e) => {
    if (e.button !== 0) return;
    hd.setPointerCapture(e.pointerId); drag = true; hd.setAttribute('data-drag', '');
    e.preventDefault(); hd.focus({ preventScroll: true });
  });
  hd.addEventListener('pointermove', (e) => { if (drag) move(e); });
  const up = () => { drag = null; hd.removeAttribute('data-drag'); };
  hd.addEventListener('pointerup', up);
  hd.addEventListener('pointercancel', up);
  hd.addEventListener('keydown', (e) => {
    const d = e.shiftKey ? 0.08 : 0.025;
    const m = { ArrowLeft: [-d, 0], ArrowRight: [d, 0], ArrowUp: [0, -d], ArrowDown: [0, d] }[e.key];
    if (!m) return;
    e.preventDefault();
    if (i < 3) {
      pools[i].x = Math.min(0.95, Math.max(0.05, pools[i].x + m[0]));
      pools[i].y = Math.min(0.94, Math.max(0.64, pools[i].y + m[1]));
    } else actor.tx = Math.min(0.85, Math.max(0.15, actor.tx + m[0]));
    touched();
  });
});
faders.forEach((f, i) => f.addEventListener('input', () => {
  level[i] = f.value / 255;
  faderOut[i].textContent = f.value;
  f.setAttribute('aria-valuetext', NAMES[i] + ' ' + f.value + ' of 255');
  touched();
}));

const ro = new ResizeObserver(() => {
  if (!root.isConnected) { ro.disconnect(); return; }
  const r = cv.getBoundingClientRect();
  if (!r.width || !r.height) return;
  dpr = Math.min(2, devicePixelRatio || 1);
  W = r.width; H = r.height;
  cv.width = Math.round(W * dpr); cv.height = Math.round(H * dpr);
  build();
  placeHandles(); draw(); legend();
});
ro.observe(cv);
const io = new IntersectionObserver((entries) => {
  if (!root.isConnected) { io.disconnect(); return; }
  visible = entries[entries.length - 1].isIntersecting;
  if (visible) kick();
});
io.observe(root);
calmQ.addEventListener?.('change', () => { if (root.isConnected) { draw(); kick(); } });
